/* ---------- image capture: resize + compress in the browser, no upload ---------- */
function compressImage(file, opt){
  opt = opt || CONFIG.photo;
  return new Promise((resolve, reject) => {
    if(!/^image\//.test(file.type)) return reject(new Error(file.name + ' is not an image.'));
    const fr = new FileReader();
    fr.onerror = () => reject(new Error('Could not read ' + file.name));
    fr.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error('Could not decode ' + file.name));
      img.onload = () => {
        let w = img.naturalWidth, h = img.naturalHeight;
        const m = Math.max(w, h);
        if(m > opt.maxEdgePx){ const k = opt.maxEdgePx / m; w = Math.round(w * k); h = Math.round(h * k); }
        const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        const ctx = cv.getContext('2d');
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        let q = opt.quality, url = cv.toDataURL('image/jpeg', q);
        while(url.length * 0.75 > opt.maxBytes && q > 0.35){ q -= 0.12; url = cv.toDataURL('image/jpeg', q); }
        resolve({ dataUrl:url, width:w, height:h, bytes:Math.round(url.length * 0.75), name:file.name });
      };
      img.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}
const fmtBytes = b => b > 1048576 ? (b / 1048576).toFixed(1) + ' MB' : Math.round(b / 1024) + ' KB';

