/* ---------- XLSX reader (needs DecompressionStream; falls back to CSV advice) ---------- */
async function readXlsx(file, sheetName){
  if(typeof DecompressionStream === 'undefined') throw new Error('This browser cannot read .xlsx directly. Pls save the sheet as CSV and upload that.');
  const buf = new Uint8Array(await file.arrayBuffer());
  const dv = new DataView(buf.buffer);
  let eocd = -1;
  for(let i = buf.length - 22; i >= 0; i--){ if(dv.getUint32(i, true) === 0x06054b50){ eocd = i; break; } }
  if(eocd < 0) throw new Error('Not a valid .xlsx file.');
  let ptr = dv.getUint32(eocd + 16, true);
  const n = dv.getUint16(eocd + 10, true), entries = {};
  for(let i=0;i<n;i++){
    const nameLen = dv.getUint16(ptr + 28, true), extLen = dv.getUint16(ptr + 30, true), cmtLen = dv.getUint16(ptr + 32, true);
    const method = dv.getUint16(ptr + 10, true), csize = dv.getUint32(ptr + 20, true), lho = dv.getUint32(ptr + 42, true);
    const name = new TextDecoder().decode(buf.subarray(ptr + 46, ptr + 46 + nameLen));
    entries[name] = { method, csize, lho };
    ptr += 46 + nameLen + extLen + cmtLen;
  }
  async function read(name){
    const e = entries[name]; if(!e) return null;
    const nl = dv.getUint16(e.lho + 26, true), el = dv.getUint16(e.lho + 28, true);
    const start = e.lho + 30 + nl + el, raw = buf.subarray(start, start + e.csize);
    if(e.method === 0) return new TextDecoder().decode(raw);
    const ds = new DecompressionStream('deflate-raw');
    const out = new Response(new Blob([raw]).stream().pipeThrough(ds));
    return await out.text();
  }
  const shared = [], ss = await read('xl/sharedStrings.xml');
  if(ss){ const re = /<si>([\s\S]*?)<\/si>/g; let m;
    while((m = re.exec(ss))){ let t = ''; const tre = /<t[^>]*>([\s\S]*?)<\/t>/g; let x;
      while((x = tre.exec(m[1]))) t += x[1];
      shared.push(t.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&')); } }
  /* Sheet lookup. Without a name we take the first worksheet, as before.
     With one we resolve it through workbook.xml and its rels, so a workbook
     carrying "TRCE USER" and "HELPDESK Team" tabs can be read directly. */
  let sheetXml = null;
  if(sheetName){
    const wb = await read('xl/workbook.xml'), rel = await read('xl/_rels/workbook.xml.rels');
    if(wb && rel){
      const want = String(sheetName).trim().toLowerCase().replace(/\s+/g, ' ');
      const sRe = /<sheet\s([^>]*?)\/?>/g; let sm, rid = '';
      while((sm = sRe.exec(wb))){
        const nm = /name="([^"]*)"/.exec(sm[1]), id = /r:id="([^"]*)"/.exec(sm[1]);
        if(nm && id){
          const got = nm[1].replace(/&amp;/g,'&').trim().toLowerCase().replace(/\s+/g, ' ');
          if(got === want){ rid = id[1]; break; }
        }
      }
      if(!rid) return null;                       // no such tab in this workbook
      const rRe = new RegExp('<Relationship[^>]*Id="' + rid + '"[^>]*Target="([^"]*)"');
      const t = rRe.exec(rel);
      if(t){ let path = t[1].replace(/^\//, ''); if(path.indexOf('xl/') !== 0) path = 'xl/' + path; sheetXml = await read(path); }
    }
    if(!sheetXml) return null;
  } else {
    sheetXml = await read('xl/worksheets/sheet1.xml');
    if(!sheetXml){ const k = Object.keys(entries).find(x => /^xl\/worksheets\/.*\.xml$/.test(x)); if(k) sheetXml = await read(k); }
    if(!sheetXml) throw new Error('No worksheet found in the file.');
  }
  const rows = [], rowRe = /<row[^>]*>([\s\S]*?)<\/row>/g; let rm;
  while((rm = rowRe.exec(sheetXml))){
    const cells = [], cRe = /<c\s([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g; let cm;
    while((cm = cRe.exec(rm[1]))){
      const attrs = cm[1] || '', inner = cm[2] || '';
      const refM = /r="([A-Z]+)\d+"/.exec(attrs);
      let ci = 0; if(refM){ const L = refM[1]; for(let i=0;i<L.length;i++) ci = ci*26 + (L.charCodeAt(i) - 64); ci--; }
      const t = /t="([^"]+)"/.exec(attrs), vM = /<v>([\s\S]*?)<\/v>/.exec(inner);
      let val = '';
      if(t && t[1] === 's') val = shared[parseInt(vM ? vM[1] : '0', 10)] || '';
      else if(t && t[1] === 'inlineStr'){ const im = /<t[^>]*>([\s\S]*?)<\/t>/.exec(inner); val = im ? im[1] : ''; }
      else if(vM) val = vM[1];
      val = String(val).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&');
      while(cells.length < ci) cells.push('');
      cells[ci] = val;
    }
    rows.push(cells);
  }
  return rows.filter(r => r.some(c => String(c).trim() !== ''));
}
/* "3 h", "18 h", "2 d" — one short label for an age given in hours */
function ageLabel(h){
  h = Math.max(0, Number(h) || 0);
  if(h < 1) return Math.round(h * 60) + ' m';
  if(h < 48) return Math.round(h) + ' h';
  return Math.round(h / 24) + ' d';
}
function cleanCell(v){
  if(v === undefined || v === null) return '';
  return String(v).replace(/_x000D_/g, '').replace(/\r\n?/g, '\n').replace(/[ \t]+\n/g, '\n').trim();
}
// Excel serial date -> ISO (dates come through as numbers when the cell is date-formatted)
function excelDate(v){
  if(v === '' || v === null || v === undefined) return '';
  if(/^\d+(\.\d+)?$/.test(String(v))){
    const n = parseFloat(v);
    if(n > 20000 && n < 80000){ const d = new Date(Date.UTC(1899, 11, 30) + n * 86400000); return ymd(d); }
  }
  const d = new Date(v); return isNaN(d) ? String(v) : ymd(d);
}

/* ============================================================
   2. UI PRIMITIVES
   ============================================================ */
function toast(msg, kind){
  const t = document.createElement('div');
  t.className = 'toast ' + (kind || '');
  t.textContent = msg;
  $('#toasts').appendChild(t);
  setTimeout(() => { t.style.opacity = '0'; t.style.transition = 'opacity .3s'; setTimeout(() => t.remove(), 320); }, kind === 'err' ? 5200 : 3200);
}

const Modal = {
  stack: [],
  open(opts){
    const ov = document.createElement('div');
    ov.className = 'ov';
    ov.innerHTML = '<div class="modal ' + (opts.size || '') + '" role="dialog" aria-modal="true">' +
      '<div class="modal-h"><h3>' + esc(opts.title) + '</h3><button class="x" aria-label="Close">&times;</button></div>' +
      '<div class="modal-b"></div>' +
      (opts.footer === false ? '' : '<div class="modal-f"></div>') + '</div>';
    const body = $('.modal-b', ov), foot = $('.modal-f', ov);
    if(typeof opts.body === 'string') body.innerHTML = opts.body; else if(opts.body) body.appendChild(opts.body);
    const h = { root: ov, body, foot, close(){ ov.remove(); Modal.stack.pop(); if(opts.onClose) opts.onClose(); } };
    (opts.buttons || []).forEach(b => {
      const btn = document.createElement('button');
      btn.className = 'btn ' + (b.cls || '');
      btn.textContent = b.label;
      btn.onclick = () => b.onClick ? b.onClick(h) : h.close();
      if(foot) foot.appendChild(btn);
    });
    $('.x', ov).onclick = () => h.close();
    ov.addEventListener('mousedown', e => { if(e.target === ov && opts.dismissable !== false) h.close(); });
    $('#modalRoot').appendChild(ov);
    Modal.stack.push(h);
    setTimeout(() => { const f = $('input,select,textarea,button.pri', body); if(f) f.focus(); }, 30);
    return h;
  }
};
document.addEventListener('keydown', e => {
  if(e.key === 'Escape' && Modal.stack.length) Modal.stack[Modal.stack.length - 1].close();
});
function confirmDlg(title, message, onYes, yesLabel, danger){
  Modal.open({ title, body: '<p style="margin:0">' + esc(message) + '</p>', buttons: [
    { label:'Cancel' },
    { label: yesLabel || 'Confirm', cls: danger ? 'dgr' : 'pri', onClick(h){ h.close(); onYes(); } }
  ]});
}

/* ---------- Combobox: server-style search, nothing preloaded ---------- */
function Combobox(mount, opts){
  const wrap = document.createElement('div');
  wrap.className = 'cb';
  wrap.innerHTML = '<input class="cb-in" placeholder="' + esc(opts.placeholder || 'Search…') + '" autocomplete="off" role="combobox" aria-expanded="false">' +
                   '<button class="cb-x" type="button" tabindex="-1" title="Clear">&times;</button>';
  const inp = $('.cb-in', wrap), clr = $('.cb-x', wrap);
  let pop = null, items = [], hi = -1, value = null;
  if(opts.disabled) inp.disabled = true;

  function close(){ if(pop){ pop.remove(); pop = null; inp.setAttribute('aria-expanded','false'); } hi = -1; }
  function pick(it){
    value = it; close();
    inp.value = it ? (opts.display ? opts.display(it) : it.label) : '';
    if(opts.onSelect) opts.onSelect(it);
  }
  function render(list){
    close();
    pop = document.createElement('div'); pop.className = 'cb-pop';
    if(!list.length){ pop.innerHTML = '<div class="cb-empty">' + esc(opts.emptyText || 'No matches. Refine the search or use a manual entry option.') + '</div>'; }
    let last = null;
    list.forEach((it, i) => {
      if(it.group && it.group !== last){ last = it.group; const g = document.createElement('div'); g.className = 'cb-sep'; g.textContent = it.group; pop.appendChild(g); }
      const d = document.createElement('div');
      d.className = 'cb-opt' + (it.special ? ' special' : '');
      d.innerHTML = '<b>' + esc(it.label) + '</b>' + (it.sub ? '<small>' + esc(it.sub) + '</small>' : '');
      d.onmousedown = e => { e.preventDefault(); pick(it); };
      d.dataset.i = i;
      pop.appendChild(d);
    });
    items = list;
    wrap.appendChild(pop);
    inp.setAttribute('aria-expanded','true');
  }
  const search = debounce(() => {
    const q = inp.value.trim();
    Promise.resolve(opts.source(q)).then(list => { if(document.activeElement === inp) render(list.slice(0, opts.limit || 50)); });
  }, 140);
  inp.addEventListener('input', () => { value = null; if(opts.onSelect && opts.clearOnType !== false) opts.onSelect(null); search(); });
  inp.addEventListener('focus', search);
  inp.addEventListener('blur', () => setTimeout(close, 120));
  inp.addEventListener('keydown', e => {
    if(!pop) return;
    const opts_ = $$('.cb-opt', pop);
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
      e.preventDefault(); hi += e.key === 'ArrowDown' ? 1 : -1;
      if(hi < 0) hi = opts_.length - 1; if(hi >= opts_.length) hi = 0;
      opts_.forEach(o => o.classList.remove('hi'));
      if(opts_[hi]){ opts_[hi].classList.add('hi'); opts_[hi].scrollIntoView({ block:'nearest' }); }
    } else if(e.key === 'Enter'){ if(hi >= 0 && items[hi]){ e.preventDefault(); pick(items[hi]); } }
    else if(e.key === 'Escape') close();
  });
  clr.onclick = () => { inp.value = ''; pick(null); inp.focus(); };
  mount.appendChild(wrap);
  return {
    el: wrap, input: inp,
    get value(){ return value; },
    set(it){ pick(it); },
    setText(t){ inp.value = t; },
    clear(){ value = null; inp.value = ''; },
    disable(b){ inp.disabled = !!b; if(b){ inp.value = ''; value = null; } },
    invalid(b){ inp.classList.toggle('err', !!b); }
  };
}

/* ---------- DataTable ---------- */
function DataTable(mount, opts){
  const state = { page: 1, size: opts.size || CONFIG.pageSize, sort: opts.sort || null, dir: opts.dir || 'desc' };
  const wrap = document.createElement('div');
  mount.appendChild(wrap);
  function draw(){
    let rows = opts.rows.slice();
    if(state.sort){
      const col = opts.cols.find(c => c.key === state.sort) || {};
      rows.sort((a, b) => {
        let x = col.sortVal ? col.sortVal(a) : a[state.sort], y = col.sortVal ? col.sortVal(b) : b[state.sort];
        x = x === null || x === undefined ? '' : x; y = y === null || y === undefined ? '' : y;
        if(typeof x === 'number' && typeof y === 'number') return state.dir === 'asc' ? x - y : y - x;
        return state.dir === 'asc' ? String(x).localeCompare(String(y)) : String(y).localeCompare(String(x));
      });
    }
    const total = rows.length, pages = Math.max(1, Math.ceil(total / state.size));
    if(state.page > pages) state.page = pages;
    const slice = rows.slice((state.page - 1) * state.size, state.page * state.size);
    let h = '<div class="tbl-wrap"><table class="tbl"><thead><tr>';
    opts.cols.forEach(c => {
      h += '<th class="' + (c.sortable === false ? '' : 'sortable ') + (c.nowrap ? 'nowrap' : '') + '" data-k="' + esc(c.key) + '">' +
        esc(c.label) + (state.sort === c.key ? (state.dir === 'asc' ? ' ↑' : ' ↓') : '') + '</th>';
    });
    h += '</tr></thead><tbody>';
    if(!slice.length){
      h += '<tr><td colspan="' + opts.cols.length + '"><div class="empty"><b>' + esc(opts.emptyTitle || 'Nothing here yet') + '</b>' + esc(opts.emptyText || '') + '</div></td></tr>';
    } else {
      slice.forEach((r, i) => {
        h += '<tr' + (opts.onRow ? ' class="clk"' : '') + ' data-i="' + i + '">';
        opts.cols.forEach(c => { h += '<td class="' + (c.nowrap ? 'nowrap' : '') + '">' + (c.render ? c.render(r, (state.page - 1) * state.size + i) : esc(r[c.key])) + '</td>'; });
        h += '</tr>';
      });
    }
    h += '</tbody></table></div><div class="tbl-foot"><span>' + total.toLocaleString('en-IN') + ' record' + (total === 1 ? '' : 's') +
      (total > state.size ? ' · page ' + state.page + ' of ' + pages : '') + '</span><div class="pager"></div></div>';
    wrap.innerHTML = h;
    const pg = $('.pager', wrap);
    if(pages > 1){
      const mk = (lbl, p, dis, on) => { const b = document.createElement('button'); b.textContent = lbl; b.disabled = !!dis; if(on) b.className = 'on'; b.onclick = () => { state.page = p; draw(); mount.scrollIntoView({ block:'nearest' }); }; pg.appendChild(b); };
      mk('‹', state.page - 1, state.page === 1);
      const from = Math.max(1, state.page - 2), to = Math.min(pages, from + 4);
      for(let p = from; p <= to; p++) mk(String(p), p, false, p === state.page);
      mk('›', state.page + 1, state.page === pages);
    }
    $$('th.sortable', wrap).forEach(th => th.onclick = () => {
      const k = th.dataset.k;
      if(state.sort === k) state.dir = state.dir === 'asc' ? 'desc' : 'asc'; else { state.sort = k; state.dir = 'asc'; }
      draw();
    });
    if(opts.onRow) $$('tbody tr.clk', wrap).forEach(tr => tr.onclick = e => {
      if(e.target.closest('button,a')) return;
      opts.onRow(slice[+tr.dataset.i]);
    });
  }
  draw();
  return { redraw(rows){ if(rows) opts.rows = rows; state.page = 1; draw(); } };
}

/* ---------- Charts (inline SVG, no library) ---------- */
const PAL = ['#0066B3','#069EDB','#D81E26','#0B8A5C','#E08A00','#7A4FD6','#0E7490','#44586B','#1D4ED8','#8A9AA9'];
function donut(data, opts){
  opts = opts || {};
  const total = data.reduce((s, d) => s + d.v, 0);
  const S = opts.compact ? 0.78 : 1;
  const R = 62 * S, r = 40 * S, cx = 78 * S, cy = 78 * S;
  if(!total) return '<div class="empty">No data yet</div>';
  let a0 = -Math.PI / 2, paths = '';
  const only = data.filter(d => d.v);
  if(only.length === 1){
    paths = '<circle cx="' + cx + '" cy="' + cy + '" r="' + ((R + r) / 2) + '" fill="none" stroke="' +
      (only[0].c || PAL[data.indexOf(only[0]) % PAL.length]) + '" stroke-width="' + (R - r) + '"><title>' +
      esc(only[0].k) + ': ' + only[0].v + '</title></circle>';
  }
  data.forEach((d, i) => {
    if(!d.v || only.length === 1) return;
    const a1 = a0 + (d.v / total) * Math.PI * 2, large = (a1 - a0) > Math.PI ? 1 : 0;
    const p = (rad, ang) => [cx + rad * Math.cos(ang), cy + rad * Math.sin(ang)];
    const [x0,y0] = p(R,a0), [x1,y1] = p(R,a1), [x2,y2] = p(r,a1), [x3,y3] = p(r,a0);
    paths += '<path d="M' + x0.toFixed(1) + ' ' + y0.toFixed(1) + ' A' + R + ' ' + R + ' 0 ' + large + ' 1 ' + x1.toFixed(1) + ' ' + y1.toFixed(1) +
      ' L' + x2.toFixed(1) + ' ' + y2.toFixed(1) + ' A' + r + ' ' + r + ' 0 ' + large + ' 0 ' + x3.toFixed(1) + ' ' + y3.toFixed(1) + ' Z" fill="' +
      (d.c || PAL[i % PAL.length]) + '"><title>' + esc(d.k) + ': ' + d.v + '</title></path>';
    a0 = a1;
  });
  return '<div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap">' +
    '<svg viewBox="0 0 ' + (156 * S) + ' ' + (156 * S) + '" width="' + (156 * S) + '" height="' + (156 * S) + '" class="chart donut-svg" style="flex:none;width:' + (156 * S) + 'px;height:' + (156 * S) + 'px">' + paths +
    '<text x="' + cx + '" y="' + (cy - 4 * S) + '" text-anchor="middle" font-size="' + (24 * S) + '" font-weight="650" fill="#17232F">' + total + '</text>' +
    '<text x="' + cx + '" y="' + (cy + 14 * S) + '" text-anchor="middle" font-size="' + (10.5 * S) + '" fill="#5F7183">' + esc(opts.centerLabel || 'total') + '</text></svg>' +
    '<div style="flex:1;min-width:150px"><div class="legend" style="' +
    (data.filter(d => d.v).length > 6
      ? 'display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:6px 14px;margin:0'
      : 'flex-direction:column;gap:6px;margin:0') + '">' +
    data.filter(d => d.v).map((d, i) => '<span style="display:flex;align-items:center;width:100%"><i style="background:' + (d.c || PAL[i % PAL.length]) + '"></i>' +
      esc(d.k) + '<b style="margin-left:auto;color:#17232F">' + d.v + '</b></span>').join('') +
    '</div></div></div>';
}
function hbars(data, opts){
  opts = opts || {};
  if(!data.length || !data.some(d => d.v)) return '<div class="empty">No data yet</div>';
  const max = Math.max.apply(null, data.map(d => d.v)) || 1;
  return data.map(d => '<div class="bar-row"><span class="nm" title="' + esc(d.k) + '">' + esc(d.k) + '</span>' +
    '<span class="track"><span class="fill" style="width:' + Math.max(2, (d.v / max) * 100) + '%;background:' + (d.c || 'var(--primary)') + '"></span></span>' +
    '<span class="v num">' + d.v + '</span></div>').join('');
}
function lineChart(labels, values){
  if(!values.length) return '<div class="empty">No data yet</div>';
  const W = 520, H = 170, pl = 34, pb = 24, pt = 12;
  const max = Math.max(4, Math.max.apply(null, values)), n = values.length;
  const x = i => pl + (n === 1 ? (W - pl) / 2 : i * (W - pl - 10) / (n - 1));
  const y = v => pt + (H - pt - pb) * (1 - v / max);
  let pts = values.map((v, i) => x(i).toFixed(1) + ',' + y(v).toFixed(1)).join(' ');
  let grid = '';
  for(let g = 0; g <= 3; g++){ const gv = max * g / 3, gy = y(gv);
    grid += '<line x1="' + pl + '" y1="' + gy.toFixed(1) + '" x2="' + W + '" y2="' + gy.toFixed(1) + '" stroke="#EDF1F5"/>' +
      '<text x="' + (pl - 6) + '" y="' + (gy + 3.5).toFixed(1) + '" font-size="9.5" fill="#8A9AA9" text-anchor="end">' + Math.round(gv) + '</text>'; }
  const dots = values.map((v, i) => '<circle cx="' + x(i).toFixed(1) + '" cy="' + y(v).toFixed(1) + '" r="3.2" fill="#0066B3"><title>' + esc(labels[i]) + ': ' + v + '</title></circle>').join('');
  const lbls = labels.map((l, i) => (n > 8 && i % 2) ? '' : '<text x="' + x(i).toFixed(1) + '" y="' + (H - 6) + '" font-size="9.5" fill="#8A9AA9" text-anchor="middle">' + esc(l) + '</text>').join('');
  const area = 'M' + x(0).toFixed(1) + ',' + (H - pb) + ' L' + pts.replace(/ /g, ' L') + ' L' + x(n - 1).toFixed(1) + ',' + (H - pb) + ' Z';
  return '<svg viewBox="0 0 ' + W + ' ' + H + '" class="chart" preserveAspectRatio="none" style="width:100%;height:170px">' + grid +
    '<path d="' + area + '" fill="rgba(14,107,168,.10)"/>' +
    '<polyline points="' + pts + '" fill="none" stroke="#0066B3" stroke-width="2" stroke-linejoin="round"/>' + dots + lbls + '</svg>';
}

/* Multi-series line chart used by the dashboard trend card */
function multiLine(labels, series){
  if(!series.length || !series[0].values.length) return '<div class="empty">No data yet</div>';
  const W = 560, H = 190, pl = 34, pb = 26, pt = 14;
  const all = series.reduce((a, s) => a.concat(s.values), []);
  const max = Math.max(4, Math.max.apply(null, all)), n = labels.length;
  const x = i => pl + (n === 1 ? (W - pl) / 2 : i * (W - pl - 12) / (n - 1));
  const y = v => pt + (H - pt - pb) * (1 - v / max);
  let grid = '';
  for(let g = 0; g <= 3; g++){ const gv = max * g / 3, gy = y(gv);
    grid += '<line x1="' + pl + '" y1="' + gy.toFixed(1) + '" x2="' + W + '" y2="' + gy.toFixed(1) + '" stroke="var(--line)"/>' +
      '<text x="' + (pl - 6) + '" y="' + (gy + 3.5).toFixed(1) + '" font-size="9.5" fill="var(--mut)" text-anchor="end">' + Math.round(gv) + '</text>'; }
  let body = '';
  series.forEach((s, si) => {
    const pts = s.values.map((v, i) => x(i).toFixed(1) + ',' + y(v).toFixed(1)).join(' ');
    if(s.area) body += '<path d="M' + x(0).toFixed(1) + ',' + (H - pb) + ' L' + pts.replace(/ /g, ' L') + ' L' + x(n - 1).toFixed(1) + ',' + (H - pb) + ' Z" fill="' + s.color + '" opacity=".10"/>';
    body += '<polyline points="' + pts + '" fill="none" stroke="' + s.color + '" stroke-width="2.2" stroke-linejoin="round"' + (s.dash ? ' stroke-dasharray="5 4"' : '') + '/>';
    body += s.values.map((v, i) => '<circle cx="' + x(i).toFixed(1) + '" cy="' + y(v).toFixed(1) + '" r="3" fill="' + s.color + '"><title>' + esc(labels[i]) + ' · ' + esc(s.name) + ': ' + v + '</title></circle>').join('');
  });
  const lbls = labels.map((l, i) => (n > 8 && i % 2) ? '' : '<text x="' + x(i).toFixed(1) + '" y="' + (H - 7) + '" font-size="9.5" fill="var(--mut)" text-anchor="middle">' + esc(l) + '</text>').join('');
  return '<svg viewBox="0 0 ' + W + ' ' + H + '" class="chart" preserveAspectRatio="none" style="width:100%;height:190px">' + grid + body + lbls + '</svg>' +
    '<div class="legend">' + series.map(s => '<span><i style="background:' + s.color + '"></i>' + esc(s.name) + '</span>').join('') + '</div>';
}

/* ===== p4_data.js ===== */
/* ============================================================
   3. STORAGE ADAPTER
   Everything below the API layer talks to this object only.
   Swap CONFIG.adapter to 'rest' to move to Express + PostgreSQL
   without touching any screen code.
   ============================================================ */
const DB_KEY = 'RCM_DB_V1';
const Store = {
  db: null,
  load(){
    if(CONFIG.adapter !== 'local') throw new Error('Adapter "' + CONFIG.adapter + '" needs the REST backend. See README.');
    let raw = null;
    try { raw = localStorage.getItem(DB_KEY); } catch(e){ /* private mode */ }
    if(raw){ try { this.db = JSON.parse(raw); } catch(e){ this.db = null; } }
    if(!this.db || this.db.schema !== 1) this.db = seedDatabase();
    else migrateDb(this.db);
    return this.db;
  },
  save(){
    try { localStorage.setItem(DB_KEY, JSON.stringify(this.db)); }
    catch(e){ toast('Browser storage is full — export your data and reset.', 'err'); }
  },
  reset(){ try { localStorage.removeItem(DB_KEY); } catch(e){} this.db = seedDatabase(); this.save(); }
};

/* ---- Application roles.  The login master (USER_LIST.xlsx / users.json) carries
   its own Role column; CONFIG.roleMap translates it to an application role, and
   an admin can override any single user in User & role management.           ---- */
/* Image bytes live in their own key: the main database is written on every
   ticket change and must stay small. Metadata stays with the call. */
const PHOTO_KEY = 'RCM_PHOTOS_V1';
const PhotoStore = {
  map: null,
  load(){ if(this.map) return this.map;
    try { this.map = JSON.parse(localStorage.getItem(PHOTO_KEY) || '{}'); } catch(e){ this.map = {}; }
    return this.map; },
  save(){ try { localStorage.setItem(PHOTO_KEY, JSON.stringify(this.map)); return true; }
    catch(e){ toast('Browser storage is full — photos could not be saved. Export a backup and clear old tickets.', 'err'); return false; } },
  put(id, dataUrl){ return true; },
  get(id){ return this.load()[id] || ''; },
  del(id){ this.load(); delete this.map[id]; this.save(); },
  bytes(){ this.load(); let n = 0; for(const k in this.map) n += this.map[k].length * 0.75; return Math.round(n); },
  reset(){ this.map = {}; try { localStorage.removeItem(PHOTO_KEY); } catch(e){} }
};

const ROLES = {
  ADMIN:    { label:'Admin',         tone:'tone-b', desc:'Sees every call and every detail. Owns masters, users, settings and audit.' },
  HELPDESK: { label:'Helpdesk Team', tone:'tone-p', desc:'Logs calls for anyone and sees all call details.' },
  TRCE:     { label:'TRCE User',     tone:'tone-n', desc:'Logs calls for himself, updates only the calls assigned to him.' }
};
const PERM_LIST = [
  ['call.view.all',     'View all calls'],
  ['call.create',       'Log a call'],
  ['call.assign',       'Log a call for another user'],
  ['call.update.all',   'Update any call'],
  ['call.update.own',   'Update own calls'],
  ['call.reassign.all', 'Reassign any call'],
  ['call.reassign.own', 'Reassign own calls'],
  ['master.manage',     'Add / edit master data'],
  ['master.import',     'Import master data'],
  ['user.manage',       'User & role management'],
  ['report.all',        'Reports on all calls'],
  ['report.own',        'Reports on own calls'],
  ['export.all',        'Export all calls'],
  ['export.own',        'Export own calls'],
  ['audit.view',        'View audit log'],
  ['settings',          'Settings']
];
const DEFAULT_PERMS = {
  ADMIN:   ['call.view.all','call.create','call.assign','call.update.all','call.update.own','call.reassign.all',
            'master.manage','master.import','user.manage','report.all','export.all','audit.view','settings'],
  HELPDESK:['call.view.all','call.create','call.assign','call.update.own','call.reassign.all','report.all','export.all'],
  TRCE:    ['call.create','call.update.own','call.reassign.own','report.own','export.own']
};
const DEFAULT_ROLE_MAP = { admin:'ADMIN', regional:'HELPDESK', branch:'HELPDESK', engineer:'TRCE' };

const STATUS_CLASS = {
  'New':'st-new','Assigned':'st-assigned','In Progress':'st-progress',
  'Pending Customer Shutdown / Update':'st-pending','Pending Spare':'st-pending','Hold':'st-hold',
  'Resolved':'st-resolved','Remote Support Closed but Engineer Required to Visit for further Assessment':'st-visit',
  'Closed':'st-closed','Reopened':'st-reopened','Cancelled':'st-cancelled'
};
/* short labels for chips, pipeline tiles and chart legends */
const STATUS_SHORT = {
  'Pending Customer Shutdown / Update':'Pending customer',
  'Remote Support Closed but Engineer Required to Visit for further Assessment':'Closed · visit needed'
};
function shortStatus(s){ return STATUS_SHORT[s] || s; }
const OPEN_STATUSES = ['New','Assigned','In Progress','Pending Customer Shutdown / Update','Pending Spare','Hold',
                       'Remote Support Closed but Engineer Required to Visit for further Assessment','Reopened'];
const DEFAULT_PW = 'ProstarM@1234';   // fallback only — used when a user-list row has no Password column, and for admin password resets

/* ---------- Seed ---------- */
/* Every configurable list in one place: seeding reads it, and a database from
   an older build is topped up from it on load. */
/* Branch and zone for an employee code, from the reference directory that ships
   with the app. Used only to fill blanks — the user file always wins. */
function zoneForBranch(branch){
  const m = (Store.db && Store.db.directory) || {}, st = String(branch || '').split('_')[0];
  let sameState = '';
  for(const k in m){
    if(m[k].branch === branch && m[k].zone) return m[k].zone;
    if(!sameState && m[k].zone && String(m[k].branch).split('_')[0] === st) sameState = m[k].zone;
  }
  return sameState;
}
function dirOf(code){
  const m = (Store.db && Store.db.directory) || {};
  return m[String(code || '').toUpperCase()] || {};
}
function defaultConfig(){
  return {
    customerSegments: ['ATM','Non ATM'],
    productPhases: ['01:01','03:01','03:03'],
    rolePerms: JSON.parse(JSON.stringify(DEFAULT_PERMS)),
    roleMap: Object.assign({}, DEFAULT_ROLE_MAP),
    assignableRoles: ['TRCE'],
    /* Role membership is a named list of employee codes, not the Role column.
       ADMIN / HELPDESK / TRCE come from the sheets of the same name in the
       user workbook. Anyone outside all three has no login. */
    roleLists: { ADMIN: [], HELPDESK: [], TRCE: [] },
    userSource: Object.assign({}, CONFIG.userSource),
    callStatuses: ['Assigned','In Progress','Pending Customer Shutdown / Update','Pending Spare','Hold','Resolved',
                   'Remote Support Closed but Engineer Required to Visit for further Assessment'],
    /* set by the system, never offered in the update dropdown */
    systemStatuses: ['New','Reopened','Closed','Cancelled'],
    supportTypes: ['Remote Support','Own Visit','Own Visit with Support Engineer'],
    tatSlabs: ['0-2 Hrs','2-4 Hrs','4-6 Hrs'],
    ticketPrefix: CONFIG.ticketPrefix
  };
}
/* A database saved by an earlier build is missing whatever was added since.
   Fill the gaps on load rather than making every screen defensive, and carry
   retired status names onto their replacements so old tickets stay valid. */
const LEGACY_STATUS = {
  'Pending Customer':'Pending Customer Shutdown / Update',
  'Pending Internal Support':'Hold',
  'Pending customer':'Pending Customer Shutdown / Update'
};
function migrateDb(db){
  const fresh = defaultConfig();
  db.config = db.config || {};
  /* lists that must exist for the forms to render */
  ['callStatuses','systemStatuses','supportTypes','tatSlabs','customerSegments','productPhases','assignableRoles']
    .forEach(k => { if(!Array.isArray(db.config[k]) || !db.config[k].length) db.config[k] = fresh[k].slice(); });
  ['roleMap','roleLists','userSource'].forEach(k => {
    if(!db.config[k] || typeof db.config[k] !== 'object') db.config[k] = JSON.parse(JSON.stringify(fresh[k]));
  });
  if(!db.config.ticketPrefix) db.config.ticketPrefix = fresh.ticketPrefix;
  /* a saved list that still holds the retired statuses is replaced outright */
  if(db.config.callStatuses.some(s => LEGACY_STATUS[s])) db.config.callStatuses = fresh.callStatuses.slice();
  if(db.config.supportTypes.indexOf('Own Visit') < 0) db.config.supportTypes = fresh.supportTypes.slice();
  /* existing rows */
  (db.calls || []).forEach(c => {
    if(LEGACY_STATUS[c.callStatus]) c.callStatus = LEGACY_STATUS[c.callStatus];
    if(c.tatSlab === undefined) c.tatSlab = '';
    if(!Array.isArray(c.photos)) c.photos = [];
  });
  (db.callUpdates || []).forEach(u => {
    if(LEGACY_STATUS[u.callStatus]) u.callStatus = LEGACY_STATUS[u.callStatus];
    if(u.tatSlab === undefined) u.tatSlab = '';
  });
  ['users','assets','supportTakenUsers','calls','callUpdates','assignHistory','history','audit']
    .forEach(k => { if(!Array.isArray(db[k])) db[k] = []; });
  if(!db.counters) db.counters = {};
  if(!db.directory) db.directory = (window.SEED_DATA.directory || []).reduce((m, r) => { m[String(r.code).toUpperCase()] = r; return m; }, {});
  return db;
}
function seedDatabase(){
  const S = window.SEED_DATA;
  const now = new Date().toISOString();
  const db = {
    schema: 1, createdAt: now,
    config: defaultConfig(),
    assets: S.assets.map((a, i) => ({ id:'A' + pad(i + 1, 5), itemGroup:a.g, oem:a.o || '', itemName:a.n, itemCode:a.c, active:true })),
    supportTakenUsers: S.supportTaken.map((u, i) => ({ id:'T' + pad(i + 1, 4), employeeId:u.id, fullName:u.name, dateOfJoining:u.doj, jobTitle:u.title, department:u.dept, subDepartment:u.sub, branch:u.br, location:u.loc, active:true })),
    users: [], calls: [], callUpdates: [], assignHistory: [], history: [], audit: [], counters: {}
  };
  /* No logins are built into this file. The Users list stays empty until the
     user workbook (ADMIN / HELPDESK Team / TRCE USER sheets) or users.json is
     loaded — from the configured URL, or from the sign-in screen. */
  db.userSync = { lastSyncAt:'', source:'', count:0 };
  db.directory = (S.directory || []).reduce((m, r) => { m[String(r.code).toUpperCase()] = r; return m; }, {});
  return db;
}

/* One login record built from a row of the user master */
function buildUserRecord(u, id, roleMap, now){
  const s = makeSalt();
  const xr = String(u.xrole || '').toLowerCase();
  return {
    id: id, employeeId: String(u.code || '').toUpperCase(), fullName: u.name,
    branch: u.branch || dirOf(u.code).branch || '',
    zone: u.zone || dirOf(u.code).zone || zoneForBranch(u.branch || dirOf(u.code).branch), designation: u.desig || '',
    managerCode: u.mgr || '', managerName: u.mgrName || '',
    department: 'Operation', location: u.loc || (u.branch || '').replace('_', '-'),
    sourceRole: xr, roleOverride: '', role: roleMap[xr] || 'TRCE',
    salt: (u.hash && u.hsalt) ? u.hsalt : s,
    passwordHash: (u.hash && u.hsalt) ? u.hash : hashPassword(u.pw || DEFAULT_PW, s), pwSource: 'SYNC',
    mustChange: false, active: true, createdAt: now, updatedAt: now
  };
}
/* A user's role is whichever named list holds their employee code.
   Nobody gets a role by job title or by the Role column any more. */
function roleFromLists(code, lists){
  const c = String(code || '').toUpperCase();
  const L = lists || (Store.db && Store.db.config.roleLists) || {};
  if((L.ADMIN || []).indexOf(c) >= 0) return 'ADMIN';
  if((L.HELPDESK || []).indexOf(c) >= 0) return 'HELPDESK';
  if((L.TRCE || []).indexOf(c) >= 0) return 'TRCE';
  return '';
}
function effectiveRole(u){ return u.roleOverride || roleFromLists(u.employeeId) || ''; }
/* Recompute every account against the lists: role, and whether they can sign in */
function applyRoleLists(db){
  db = db || Store.db;
  const L = db.config.roleLists || {};
  db.users.forEach(u => {
    const r = u.roleOverride || roleFromLists(u.employeeId, L);
    u.role = r;
    u.inRoleList = !!r;
    if(!r) u.active = false;
    else if(u.deactivated !== true) u.active = true;
  });
  return db.users.filter(u => u.inRoleList).length;
}

/* Deterministic demo tickets so the dashboard and reports are meaningful on day one */
function seedDemoCalls(db){
  let s = 20260910;
  const rnd = () => { s = (s * 1103515245 + 12345) % 2147483648; return s / 2147483648; };
  const pick = a => a[Math.floor(rnd() * a.length)];
  const customers = [
    ['India1 Payments','ATM'],['CMS Info Systems','ATM'],['Hitachi Payment Services','ATM'],['AGS Transact','ATM'],
    ['NCR Corporation','ATM'],['Euronet Services','ATM'],['SBI ATM Cell','ATM'],
    ['State Bank of India','Non ATM'],['HDFC Bank','Non ATM'],['Bank of Baroda','Non ATM'],['AIIMS Delhi','Non ATM'],
    ['NTPC Ltd','Non ATM'],['Tata Motors','Non ATM'],['Wipro Ltd','Non ATM'],['IIT Kharagpur','Non ATM'],['BSNL','Non ATM']
  ];
  const issues = [
    'UPS going to bypass intermittently during load transfer.','Battery backup time dropped to under 4 minutes.',
    'Display showing fault code F06 and audible alarm continuous.','SNMP card not reachable from the monitoring portal.',
    'Output voltage fluctuating beyond acceptable band.','Unit not charging after mains restoration.',
    'Frequent overload trip reported by branch staff.','Cooling fan noise and temperature alarm on inverter module.',
    'Site reports total shutdown of the UPS during power cut.','Isolation transformer humming with abnormal heating.'
  ];
  const found = [
    'Bypass SCR firing card found faulty.','Two battery strings measured below 10.5V under load.',
    'Loose DC bus connection at the terminal block.','Network patch cable and switch port were down at site.',
    'Firmware version outdated, control card needed re-flash.','Charger fuse blown due to input surge.',
    'Actual connected load exceeded rated capacity by 22%.','Fan bearing worn out, replacement required.'
  ];
  const actions = [
    'Guided site engineer through card replacement, unit restored and load transferred back.',
    'Advised battery replacement, quotation shared with the branch.',
    'Connections tightened and torque checked; unit is stable now.',
    'Coordinated with the customer IT team, port re-enabled and monitoring restored.',
    'Firmware upgraded remotely and parameters reset to site standard.',
    'Fuse replaced and charging verified for 30 minutes.',
    'Load audit shared and the customer agreed to shift non-critical load.'
  ];
  const spares = ['SCR Firing Card','Battery 12V 42AH','Cooling Fan 120mm','Charger Fuse 32A','SNMP Card','Control Card'];
  const rsUsers = db.users.filter(u => db.config.assignableRoles.indexOf(u.role) >= 0);
  const closedish = ['Closed','Closed','Closed','Closed','Resolved','Resolved','Reopened','Cancelled'];
  const openish = ['New','Assigned','In Progress','In Progress','Pending Spare','Pending Customer Shutdown / Update','Hold','Remote Support Closed but Engineer Required to Visit for further Assessment'];
  const today = new Date();

  for(let i = 0; i < 58; i++){
    const daysAgo = Math.floor(rnd() * 165);
    const raised = new Date(today.getTime() - daysAgo * 86400000 - Math.floor(rnd() * 8) * 3600000);
    const asset = db.assets[Math.floor(rnd() * db.assets.length)];
    const owner = pick(rsUsers);
    const cust = pick(customers);
    const isClosed = daysAgo > 12 ? rnd() < 0.74 : rnd() < 0.22;
    const status = isClosed ? pick(closedish) : pick(openish);
    const tid = nextTicketId(db, raised);
    const call = {
      id: uid(), ticketId: tid, ticketRaiseDate: raised.toISOString(),
      assignedEmpId: owner.employeeId, assignedEmpName: owner.fullName,
      customerName: cust[0], customerSegment: cust[1],
      productSelectionType: 'MASTER',
      itemGroup: asset.itemGroup, oem: asset.oem, itemName: asset.itemName, itemCode: asset.itemCode,
      otherProduct: null,
      productPhase: pick(db.config.productPhases.concat(['01:01','01:01','03:01'])),
      issueReported: pick(issues),
      callStatus: status,
      createdBy: (() => { const desk = db.users.filter(u => u.role === 'ADMIN' || u.role === 'HELPDESK');
        return (rnd() < 0.55 && desk.length) ? pick(desk).employeeId : owner.employeeId; })(),
      createdAt: raised.toISOString(), updatedAt: raised.toISOString(),
      reopenDate: status === 'Reopened' ? new Date(raised.getTime() + 6 * 86400000).toISOString() : '',
      detailsIssueFound: '', supportType: '', recipientType: '', givenToId: '', givenToName: '',
      otherRecipient: null, directCustomer: null,
      supportEngineerId: '', supportEngineerName: '',
      correctiveAction: '', spareRequired: '', spareName: '', tatSlab: '', ticketUpdationDate: '', photos: []
    };
    db.history.push(hist(call.ticketId, 'CREATED', '', 'Call logged for ' + call.customerName, call.createdBy, raised.toISOString(), ''));
    db.history.push(hist(call.ticketId, 'ASSIGNED', '', owner.employeeId + ' – ' + owner.fullName, call.createdBy, raised.toISOString(), 'Initial assignment'));

    if(status !== 'New' && status !== 'Assigned'){
      const upd = new Date(raised.getTime() + (1 + Math.floor(rnd() * 5)) * 86400000);
      const remote = rnd() < 0.72;
      call.detailsIssueFound = pick(found);
      call.supportType = remote ? 'Remote Support' : (rnd() < 0.5 ? 'Own Visit' : 'Own Visit with Support Engineer');
      if(remote){
        const roll = rnd();
        if(roll < 0.72){
          const t = db.supportTakenUsers[Math.floor(rnd() * db.supportTakenUsers.length)];
          call.recipientType = 'MASTER_USER'; call.givenToId = t.employeeId; call.givenToName = t.fullName;
        } else if(roll < 0.9){
          call.recipientType = 'DIRECT_CUSTOMER'; call.givenToId = ''; call.givenToName = 'Direct Customer';
          call.directCustomer = { contactPerson:'Branch Manager', contactNumber:'', email:'', location:cust[0], remarks:'Support given directly to customer team.' };
        } else {
          call.recipientType = 'OTHER_USER'; call.givenToId = 'EXT-' + (100 + Math.floor(rnd() * 800));
          call.givenToName = pick(['Suresh Nair','Vinod Chauhan','Ritika Sen','Mohan Das']);
          call.otherRecipient = { refId:call.givenToId, name:call.givenToName, jobTitle:'Site Engineer', department:'Customer Site', subDepartment:'', branch:'', location:cust[0], contact:'', email:'', remarks:'Not available in support taken master.' };
        }
      } else {
        const eng = pick(db.supportTakenUsers.filter(u => /Engineer/i.test(u.jobTitle)));
        call.supportEngineerId = eng.employeeId; call.supportEngineerName = eng.fullName;
      }
      call.correctiveAction = pick(actions);
      call.spareRequired = rnd() < 0.42 ? 'Yes' : 'No';
      call.spareName = call.spareRequired === 'Yes' ? pick(spares) : '';
      call.tatSlab = pick(db.config.tatSlabs);
      call.ticketUpdationDate = upd.toISOString();
      call.updatedAt = upd.toISOString();
      db.callUpdates.push({
        id: uid(), ticketId: call.ticketId, detailsIssueFound: call.detailsIssueFound, supportType: call.supportType,
        recipientType: call.recipientType, givenToId: call.givenToId, givenToName: call.givenToName,
        otherRecipient: call.otherRecipient, directCustomer: call.directCustomer,
        supportEngineerId: call.supportEngineerId, supportEngineerName: call.supportEngineerName,
        correctiveAction: call.correctiveAction, spareRequired: call.spareRequired, spareName: call.spareName, tatSlab: call.tatSlab,
        callStatus: call.callStatus, updatedBy: owner.employeeId, ticketUpdationDate: upd.toISOString()
      });
      db.history.push(hist(call.ticketId, 'UPDATED', 'Assigned', call.callStatus, owner.employeeId, upd.toISOString(), call.supportType));
    }
    db.calls.push(call);
  }
  db.calls.sort((a, b) => a.ticketRaiseDate < b.ticketRaiseDate ? 1 : -1);
  db.calls.forEach((c, i) => c.srNo = db.calls.length - i);
  return db;
}
function hist(ticketId, action, oldV, newV, by, at, remarks){
  return { id: uid(), ticketId, action, oldValue: oldV || '', newValue: newV || '', performedBy: by, performedAt: at || new Date().toISOString(), remarks: remarks || '' };
}
function nextTicketId(db, when){
  const d = when ? new Date(when) : new Date();
  const key = ymd(d).replace(/-/g, '');
  db.counters[key] = (db.counters[key] || 0) + 1;
  let id = db.config.ticketPrefix + '-' + key + '-' + pad(db.counters[key], 4);
  while(db.calls.some(c => c.ticketId === id)){
    db.counters[key]++; id = db.config.ticketPrefix + '-' + key + '-' + pad(db.counters[key], 4);
  }
  return id;
}

/* ============================================================
   4. SESSION + AUTHORISATION
   Every API call re-checks permissions here, independent of what
   the UI happens to be showing. With the REST adapter the same
   checks must also run on the server (see README §Security).
   ============================================================ */
const Session = {
  user: null, startedAt: 0,
  restore(){
    let raw = null; try { raw = sessionStorage.getItem('RCM_SESSION'); } catch(e){}
    if(!raw) return null;
    const s = JSON.parse(raw);
    if(Date.now() - s.startedAt > CONFIG.sessionMinutes * 60000){ this.destroy(); return null; }
    const u = Store.db.users.find(x => x.employeeId === s.employeeId);
    if(!u || !u.active) { this.destroy(); return null; }
    this.user = u; this.startedAt = s.startedAt; return u;
  },
  create(u){
    this.user = u; this.startedAt = Date.now();
    try { sessionStorage.setItem('RCM_SESSION', JSON.stringify({ employeeId:u.employeeId, startedAt:this.startedAt })); } catch(e){}
  },
  touch(){ this.startedAt = Date.now(); try { sessionStorage.setItem('RCM_SESSION', JSON.stringify({ employeeId:this.user.employeeId, startedAt:this.startedAt })); } catch(e){} },
  destroy(){ this.user = null; try { sessionStorage.removeItem('RCM_SESSION'); } catch(e){} }
};
function permsFor(role){
  const cfg = Store.db && Store.db.config && Store.db.config.rolePerms;
  return (cfg && cfg[role]) || DEFAULT_PERMS[role] || [];
}
function can(perm){
  const u = Session.user; if(!u) return false;
  return permsFor(u.role).indexOf(perm) >= 0;
}
function isHD(){ return can('call.view.all'); }
function isAdmin(){ return Session.user && Session.user.role === 'ADMIN'; }
function requireAuth(){ if(!Session.user) throw new Error('Session expired. Pls sign in again.'); }
function ownsCall(call){ return Session.user && call.assignedEmpId === Session.user.employeeId; }

/* A login/refresh pulls the ticket list from SharePoint and used to just
   replace Store.db.calls wholesale. If an update or reassignment made on
   this device hadn't reached SharePoint yet (network blip, flow failure),
   that overwrite silently erased it. This keeps any ticket still flagged
   pendingSync exactly as it is on this device, and only accepts the
   server's copy for everything else. */
function mergeServerCalls(serverRows){
  const pendingById = {};
  Store.db.calls.forEach(c => { if(c.pendingSync) pendingById[c.ticketId] = c; });
  const merged = serverRows.map(row => pendingById[row.ticketId] || row);
  Object.keys(pendingById).forEach(id => {
    if(!merged.some(r => r.ticketId === id)) merged.push(pendingById[id]);
  });
  Store.db.calls = merged;
}

/* ============================================================
   SHAREPOINT SIGN-IN
   rcm-auth-login  → checks employee code + password in the Users list
   rcm-masters-get → { what:'users' } returns the directory (no passwords),
                     used for the "Remote support assigned to" list
   ============================================================ */
function spField(o, names){
  for(const n of names){
    let v = o && o[n];
    if(v && typeof v === 'object' && 'Value' in v) v = v.Value;      // SharePoint Choice column
    if(v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}
function spRole(raw){
  const r = String(raw || '').trim().toUpperCase().replace(/\s+/g, ' ');
  if(r === 'ADMIN' || r === 'HO ADMIN') return 'ADMIN';
  if(r === 'HELPDESK' || r === 'HELPDESK TEAM' || r === 'HELP DESK' || r === 'HELP DESK TEAM') return 'HELPDESK';
  if(r === 'TRCE' || r === 'TRCE USER' || r === 'ENGINEER') return 'TRCE';
  return '';
}
function spPerson(o){
  const code = spField(o, ['employeeId','EmployeeID','EmpCode','Title','Employee ID']).toUpperCase();
  const branch = spField(o, ['branch','Branch']) || spField(o, ['location','Location']).replace('-', '_');
  return {
    employeeId: code,
    fullName: spField(o, ['fullName','FullName','Full Name','name']) || code,
    role: spRole(spField(o, ['role','AppRole','Role','appRole'])),
    branch: branch,
    zone: spField(o, ['zone','Zone']) || (typeof zoneForBranch === 'function' ? zoneForBranch(branch) : ''),
    designation: spField(o, ['designation','Designation','Job Title','jobTitle']),
    active: !/^(no|false|0)$/i.test(spField(o, ['active','Active']) || 'yes')
  };
}
/* keep a local profile so sessions, "my calls" and reports work — never a password */
function upsertSpUser(p){
  if(!p.employeeId || !p.role) return null;
  let u = Store.db.users.find(x => x.employeeId.toUpperCase() === p.employeeId);
  const now = new Date().toISOString();
  if(!u){
    u = { id:'U' + String(Store.db.users.length + 1).padStart(4, '0'), employeeId:p.employeeId,
          department:'Operation', managerCode:'', managerName:'', roleOverride:'',
          salt:'', passwordHash:'', pwSource:'SHAREPOINT', mustChange:false, createdAt:now };
    Store.db.users.push(u);
  }
  Object.assign(u, { fullName:p.fullName, role:p.role, sourceRole:p.role.toLowerCase(),
    branch:p.branch || u.branch || '', zone:p.zone || u.zone || '', designation:p.designation || u.designation || '',
    location:(p.branch || '').replace('_', '-'), active:p.active, inRoleList:true, updatedAt:now });
  const L = Store.db.config.roleLists = Store.db.config.roleLists || { ADMIN:[], HELPDESK:[], TRCE:[] };
  ['ADMIN','HELPDESK','TRCE'].forEach(r => { L[r] = (L[r] || []).filter(c => c !== u.employeeId); });
  L[p.role].push(u.employeeId);
  return u;
}
async function spPost(url, payload){
  let res;
  try {
    res = await fetch(url, { method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify(payload) });
  } catch(e){
    throw new Error('Could not reach SharePoint. Check your connection and try again.');
  }
  let body = null;
  try { body = await res.json(); } catch(e){}
  return { status:res.status, body:body || {} };
}
async function spAuthenticate(id, password){
  if(!CONFIG.flows || !CONFIG.flows.login) throw new Error('Sign-in is not configured — the login flow URL is missing.');
  const r = await spPost(CONFIG.flows.login, { employeeId:id, password:password });
  const b = r.body;
  const ok = r.status >= 200 && r.status < 300 && b.ok !== false;
  const rec = b.data && typeof b.data === 'object' ? b.data : b;
  if(!ok || !spField(rec, ['employeeId','EmployeeID','EmpCode','Title','fullName','FullName']))
    throw new Error(r.status === 401 || r.status === 404 || b.ok === false || r.status < 300
      ? 'Employee ID or password is incorrect.'
      : 'Sign-in service error (' + r.status + '). Pls try again or contact the HD admin.');
  const p = spPerson(rec);
  if(!p.employeeId) p.employeeId = id;
  if(!p.role) throw new Error('Your account has no role in the SharePoint user list. Pls contact the HD admin.');
  if(!p.active) throw new Error('This account is inactive. Contact the HD team.');
  const u = upsertSpUser(p);
  Store.db.userSync = { lastSyncAt:new Date().toISOString(), source:'SharePoint', count:Store.db.users.length };
  Store.save();
  return u;
}
/* Directory for assignment lists — role, branch, zone only. Quiet on failure. */
async function spLoadDirectory(){
  if(!CONFIG.flows || !CONFIG.flows.masters) return 0;
  try {
    const r = await spPost(CONFIG.flows.masters, { what:'users' });
    const b = r.body, d = b.data || b;
    const rows = Array.isArray(d) ? d : (d.rows || d.value || b.value || []);
    let n = 0;
    rows.forEach(o => { if(upsertSpUser(spPerson(o))) n++; });
    if(n){ Store.save(); }
    return n;
  } catch(e){ console.error('User directory', e); return 0; }
}

/* ============================================================
   5. API LAYER  (the only thing screens are allowed to call)
   ============================================================ */
const API = {
  /* ---- auth ---- */
async login(employeeId, password){
    const id = String(employeeId || '').trim().toUpperCase();
    if(!id || !password) throw new Error('Enter your employee code and password.');
    /* Sign-in is checked by the rcm-auth-login flow against the SharePoint
       Users list. Nothing is compared in the browser and no password is kept. */
    const u = await spAuthenticate(id, password);

    Session.create(u);
    this.audit('LOGIN', '', '', '', 'Signed in');
    
    // JADOO: Await lagane se app tab tak aage nahi badhegi jab tak Flow live data na bhej de
    if (CONFIG.flows && CONFIG.flows.callsList) {
      try {
        const res = await fetch(CONFIG.flows.callsList, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ employeeId: u.employeeId, role: u.role })
        });
        
        const callData = await res.json();
        
        if(callData.ok) {
          const tickets = callData.data.rows || [];

          // SharePoint se aaye Capital keys ko Frontend Variables mein Map karein
          const mappedTickets = tickets.map(t => {
            let base = {};
            if(t.RawPayload && typeof t.RawPayload === 'string') {
              try { base = JSON.parse(t.RawPayload); } catch(e){}
            }
            
            return Object.assign(base, {
              id: t.ID || t.id || base.id,
              ticketId: t.Title || t.ticketId || base.ticketId,
              ticketRaiseDate: t.TicketRaiseDate || t.ticketRaiseDate || base.ticketRaiseDate,
              assignedEmpId: t.AssignedEmpID || t.assignedEmpId || base.assignedEmpId,
              assignedEmpName: t.AssignedEmpName || t.assignedEmpName || base.assignedEmpName,
              customerName: t.CustomerName || t.customerName || base.customerName,
              customerSegment: t.CustomerSegment || t.customerSegment || base.customerSegment,
              itemGroup: t.ItemGroup || t.itemGroup || base.itemGroup,
              itemName: t.ItemName || t.itemName || base.itemName,
              itemCode: t.ItemCode || t.itemCode || base.itemCode,
              oem: t.OEM || t.oem || base.oem,
              productPhase: t.ProductPhase || t.productPhase || base.productPhase,
              issueReported: t.IssueReported || t.issueReported || base.issueReported,
              callStatus: t.CallStatus || t.callStatus || base.callStatus,
              createdBy: t.CreatedByEmp || t.createdBy || base.createdBy,
              photoUrl: t.PhotoURL || t.photoUrl || base.photoUrl,
              ticketUpdationDate: t.TicketUpdationDate || t.ticketUpdationDate || base.ticketUpdationDate,
              reopenDate: t.ReopenDate || t.reopenDate || base.reopenDate,
              photos: t.photos || []
            });
          });

          // Local photos backup (taaki photos na udein)
          const localPhotosByTicket = {};
          Store.db.calls.forEach(c => { if((c.photos || []).length) localPhotosByTicket[c.ticketId] = c.photos; });
          
          mappedTickets.forEach(t => { 
            if(!t.photos.length && localPhotosByTicket[t.ticketId]) t.photos = localPhotosByTicket[t.ticketId]; 
          });

          // ASLI FIX: Purana Local Storage ka data puri tarah uda kar NAYA FLOW DATA save karein
          Store.db.calls = mappedTickets;
          Store.save();
        }
      } catch(e) {
        console.error('Ticket sync failed', e);
        // Agar network error aaye toh app purane local data se khul jayegi
      }
    }
    
    return u;
  },
  logout(){ if(Session.user) this.audit('LOGOUT', '', '', '', 'Signed out'); Session.destroy(); },
  changePassword(employeeId, newPw){
    requireAuth();
    if(employeeId !== Session.user.employeeId && !can('user.manage')) throw new Error('Not allowed.');
    const u = Store.db.users.find(x => x.employeeId === employeeId);
    if(!u) throw new Error('User not found.');
    if(String(newPw).length < 8) throw new Error('Password must be at least 8 characters.');
    u.salt = makeSalt(); u.passwordHash = hashPassword(newPw, u.salt); u.mustChange = false; u.pwSource = 'LOCAL'; u.updatedAt = new Date().toISOString();
    this.audit('PASSWORD_CHANGE', '', '', employeeId, 'Password updated');
    Store.save();
  },

  /* ---- audit ---- */
  audit(action, ticketId, oldV, newV, remarks){
    Store.db.audit.unshift({
      id: uid(), userId: Session.user ? Session.user.id : '', employeeId: Session.user ? Session.user.employeeId : 'anonymous',
      userName: Session.user ? Session.user.fullName : '', action, ticketId: ticketId || '',
      oldValue: oldV || '', newValue: newV || '', remarks: remarks || '', timestamp: new Date().toISOString(),
      client: navigator.userAgent.slice(0, 90)
    });
    if(Store.db.audit.length > 4000) Store.db.audit.length = 4000;
    Store.save();
  },

  /* ---- calls ---- */
  calls(filter){
    requireAuth();
    let rows = Store.db.calls.slice();
    if(!can('call.view.all')) rows = rows.filter(c => c.assignedEmpId === Session.user.employeeId || c.createdBy === Session.user.employeeId);
    return filter ? rows.filter(filter) : rows;
  },
  call(ticketId){
    requireAuth();
    const c = Store.db.calls.find(x => x.ticketId === ticketId);
    if(!c) throw new Error('Ticket not found.');
    if(!can('call.view.all') && c.assignedEmpId !== Session.user.employeeId && c.createdBy !== Session.user.employeeId)
      throw new Error('You are not authorised to view ' + ticketId + '.');
    return c;
  },
  async createCall(p){
    requireAuth();
    if(!can('call.create') && !can('call.create.self')) throw new Error('Not allowed to create calls.');
    let owner = can('call.assign') ? Store.db.users.find(u => u.employeeId === p.assignedEmpId && u.active) : Session.user;
    if(can('call.assign') && !owner) throw new Error('Select an active remote support user.');

    // 1. SharePoint Flow 3 (Create Call) ko data bhejein
    const payload = {
      assignedEmpId: owner.employeeId,
      assignedEmpName: owner.fullName,
      customerName: p.customerName.trim(),
      customerSegment: p.customerSegment,
      productSelectionType: p.productSelectionType,
      itemCode: p.productSelectionType === 'OTHER' ? (p.otherProduct.itemCode || '') : (p.itemCode || ''),
      itemGroup: p.productSelectionType === 'OTHER' ? (p.otherProduct.itemGroup || '') : (p.itemGroup || ''),
      oem: p.productSelectionType === 'OTHER' ? (p.otherProduct.oem || '') : (p.oem || ''),
      itemName: p.productSelectionType === 'OTHER' ? (p.otherProduct.itemName || '') : (p.itemName || ''),
      otherProductDescription: p.productSelectionType === 'OTHER' ? p.otherProduct.description : '',
      productPhase: p.productPhase,
      issueReported: p.issueReported.trim(),
      createdBy: Session.user.employeeId
    };

    const res = await fetch(CONFIG.flows.callCreate, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if(!data.ok) throw new Error(data.error || 'Failed to create ticket in SharePoint');

    // 2. Flow 3 ne jo naya Ticket ID (RCS-xxx) banaya hai, usey local save karein taaki UI pe dikhe
    const now = new Date();
    const call = {
      id: data.data.id, ticketId: data.data.ticketId, ticketRaiseDate: data.data.ticketRaiseDate,
      assignedEmpId: payload.assignedEmpId, assignedEmpName: payload.assignedEmpName,
      customerName: payload.customerName, customerSegment: payload.customerSegment,
      productSelectionType: payload.productSelectionType,
      itemGroup: payload.itemGroup, oem: payload.oem, itemName: payload.itemName, itemCode: payload.itemCode,
      otherProduct: p.productSelectionType === 'OTHER' ? p.otherProduct : null,
      productPhase: payload.productPhase, issueReported: payload.issueReported,
      callStatus: data.data.callStatus, createdBy: payload.createdBy,
      createdAt: now.toISOString(), updatedAt: now.toISOString(), reopenDate: '',
      detailsIssueFound: '', supportType: '', recipientType: '', givenToId: '', givenToName: '',
      otherRecipient: null, directCustomer: null, supportEngineerId: '', supportEngineerName: '',
      correctiveAction: '', spareRequired: '', spareName: '', tatSlab: '', ticketUpdationDate: '', photos: []
    };
    Store.db.calls.unshift(call);
    Store.save();
    return call;
  },
  updateCall(ticketId, p){
    requireAuth();
    const c = this.call(ticketId);
    if(!can('call.update.all') && !(can('call.update.own') && ownsCall(c)))
      throw new Error('Only the assigned user or an admin can update ' + ticketId + '.');
    if(['Closed','Cancelled'].indexOf(c.callStatus) >= 0 && p.callStatus !== 'Reopened' && !can('call.update.all'))
      throw new Error('A closed ticket can only be reopened.');
    const now = new Date(), prevStatus = c.callStatus;
    if(prevStatus === 'Closed' && p.callStatus === 'Reopened'){
      c.reopenDate = now.toISOString();
      Store.db.history.push(hist(ticketId, 'REOPENED', 'Closed', 'Reopened', Session.user.employeeId, now.toISOString(), p.remarks || ''));
      this.audit('CALL_REOPEN', ticketId, 'Closed', 'Reopened', '');
    }
    Object.assign(c, {
      detailsIssueFound: p.detailsIssueFound, supportType: p.supportType,
      recipientType: p.recipientType || '', givenToId: p.givenToId || '', givenToName: p.givenToName || '',
      otherRecipient: p.recipientType === 'OTHER_USER' ? p.otherRecipient : null,
      directCustomer: p.recipientType === 'DIRECT_CUSTOMER' ? p.directCustomer : null,
      supportEngineerId: p.supportEngineerId || '', supportEngineerName: p.supportEngineerName || '',
      correctiveAction: p.correctiveAction || '', spareRequired: p.spareRequired || '',
      spareName: p.spareRequired === 'Yes' ? p.spareName : '', tatSlab: p.tatSlab || '',
      callStatus: p.callStatus, ticketUpdationDate: now.toISOString(), updatedAt: now.toISOString()
    });
    Store.db.callUpdates.push({
      id: uid(), ticketId, detailsIssueFound: c.detailsIssueFound, supportType: c.supportType,
      recipientType: c.recipientType, givenToId: c.givenToId, givenToName: c.givenToName,
      otherRecipient: c.otherRecipient, directCustomer: c.directCustomer,
      supportEngineerId: c.supportEngineerId, supportEngineerName: c.supportEngineerName,
      correctiveAction: c.correctiveAction, spareRequired: c.spareRequired, spareName: c.spareName, tatSlab: c.tatSlab,
      callStatus: c.callStatus, updatedBy: Session.user.employeeId, ticketUpdationDate: now.toISOString()
    });
    Store.db.history.push(hist(ticketId, 'UPDATED', prevStatus, c.callStatus, Session.user.employeeId, now.toISOString(),
      c.supportType + (c.recipientType ? ' → ' + (c.givenToName || c.recipientType) : '')));
    if(prevStatus !== c.callStatus)
      Store.db.history.push(hist(ticketId, 'STATUS', prevStatus, c.callStatus, Session.user.employeeId, now.toISOString(), ''));
    if(c.recipientType === 'DIRECT_CUSTOMER') this.audit('DIRECT_CUSTOMER', ticketId, '', 'Direct Customer', '');
    if(c.recipientType === 'OTHER_USER') this.audit('OTHER_RECIPIENT', ticketId, '', c.givenToName, 'Manual recipient entry');
    this.audit('CALL_UPDATE', ticketId, prevStatus, c.callStatus, c.supportType);
    Store.save();
    return c;
  },
  reassign(ticketId, newEmpId, reason){
    requireAuth();
    const c = this.call(ticketId);
    if(!can('call.reassign.all') && !ownsCall(c)) throw new Error('You can only reassign a call currently assigned to you.');
    const nu = Store.db.users.find(u => u.employeeId === newEmpId && u.active);
    if(!nu) throw new Error('Select an active remote support user.');
    if(nu.employeeId === c.assignedEmpId) throw new Error('The call is already assigned to ' + nu.employeeId + '.');
    if(!reason || reason.trim().length < 5) throw new Error('Pls give a reason for the reassignment.');
    const now = new Date().toISOString();
    Store.db.assignHistory.push({ id: uid(), ticketId, previousEmpId: c.assignedEmpId, previousEmpName: c.assignedEmpName,
      newEmpId: nu.employeeId, newEmpName: nu.fullName, reassignedBy: Session.user.employeeId, reassignedAt: now, reason: reason.trim() });
    Store.db.history.push(hist(ticketId, 'REASSIGNED', c.assignedEmpId + ' – ' + c.assignedEmpName, nu.employeeId + ' – ' + nu.fullName, Session.user.employeeId, now, reason.trim()));
    c.assignedEmpId = nu.employeeId; c.assignedEmpName = nu.fullName; c.updatedAt = now;
    if(c.callStatus === 'New') c.callStatus = 'Assigned';
    this.audit('CALL_REASSIGN', ticketId, '', nu.employeeId, reason.trim());
    Store.save();
    return c;
  },
  history(ticketId){ requireAuth(); this.call(ticketId);
    return Store.db.history.filter(h => h.ticketId === ticketId).sort((a, b) => a.performedAt < b.performedAt ? -1 : 1); },
  updates(ticketId){ requireAuth(); this.call(ticketId);
    return Store.db.callUpdates.filter(u => u.ticketId === ticketId).sort((a, b) => a.ticketUpdationDate < b.ticketUpdationDate ? 1 : -1); },
  assignments(ticketId){ requireAuth(); this.call(ticketId);
    return Store.db.assignHistory.filter(a => a.ticketId === ticketId).sort((a, b) => a.reassignedAt < b.reassignedAt ? 1 : -1); },

  /* ---- masters (search returns a capped slice, like a server would) ---- */
  searchAssets(q, filters, limit){
    const t = (q || '').toLowerCase().split(/\s+/).filter(Boolean);
    const out = [];
    for(const a of Store.db.assets){
      if(!a.active) continue;
      if(filters){
        if(filters.itemGroup && a.itemGroup !== filters.itemGroup) continue;
        if(filters.oem && (a.oem || '') !== filters.oem) continue;
        if(filters.itemName && a.itemName !== filters.itemName) continue;
      }
      const hay = (a.itemCode + ' ' + a.itemName + ' ' + a.itemGroup + ' ' + a.oem).toLowerCase();
      if(t.every(w => hay.indexOf(w) >= 0)) out.push(a);
      if(out.length >= (limit || 50)) break;
    }
    return out;
  },
  searchSupportTaken(q, limit){
    const t = (q || '').toLowerCase().split(/\s+/).filter(Boolean);
    const out = [];
    for(const u of Store.db.supportTakenUsers){
      if(!u.active) continue;
      const hay = (u.employeeId + ' ' + u.fullName + ' ' + u.jobTitle + ' ' + u.department + ' ' + u.subDepartment + ' ' + u.branch + ' ' + u.location).toLowerCase();
      if(t.every(w => hay.indexOf(w) >= 0)) out.push(u);
      if(out.length >= (limit || 40)) break;
    }
    return out;
  },
  activeUsers(){
    const ok = Store.db.config.assignableRoles || ['TRCE'];
    return Store.db.users.filter(u => u.active && ok.indexOf(u.role) >= 0);
  },
  allUsers(){ return Store.db.users.slice(); },

  /* ---- photos ---- */
  async addPhotos(ticketId, stage, items){
    requireAuth();
    const c = this.call(ticketId);
    c.photos = c.photos || [];
    const out = [];

    for (let it of items) {
      let base64Data = it.dataUrl.split(',')[1];
      try {
        let res = await fetch(CONFIG.flows.photoUpload, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ticketId: ticketId,
            stage: stage,
            fileName: it.name,
            contentType: 'image/jpeg',
            base64: base64Data,
            employeeId: Session.user.employeeId
          })
        });
        let data = await res.json();
        if(data.ok) {
          // JADOO: Har photo ka apna individual URL yahan alag save hoga
          out.push({
            id: data.data.id,
            ticketId: ticketId,
            stage: stage,
            name: it.name,
            bytes: it.bytes,
            url: data.data.url, 
            at: new Date().toISOString()
          });
        }
      } catch(e) {
        console.error('Photo upload error:', e);
      }
    }
    
    if(out.length){
      c.photos.push(...out);
      Store.save();
    }
    return out;
  },

  /* Pulls this ticket's real photo list from SharePoint (Flow: rcm-photos-list).
     Needed because Flow 2 (calls list) only ever returns a PhotoCount number, not
     the files themselves — without this, nobody but the original uploader's own
     browser, in that same session, ever sees an uploaded photo again. */
  async loadPhotos(ticketId){
    requireAuth();
    const c = this.call(ticketId);
    if(!CONFIG.flows || !CONFIG.flows.photosList) return c.photos || [];
    try {
      const res = await fetch(CONFIG.flows.photosList, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ticketId: ticketId })
      });
      const data = await res.json();
      if(data.ok && Array.isArray(data.data.rows)){
        c.photos = data.data.rows.map(r => ({
          id: String(r.id), ticketId: ticketId, stage: r.stage || 'LOG',
          name: r.name || '', bytes: 0, url: r.url || '', by: r.by || '', at: r.at || ''
        }));
        Store.save();
      }
    } catch(e){ console.error('Photo list fetch failed', e); }
    return c.photos || [];
  },

  photoData(id){
    let ticket = Store.db.calls.find(c => (c.photos || []).some(p => p.id === id));
    if (ticket && ticket.photos) {
       let photo = ticket.photos.find(p => p.id === id);
       if (photo && photo.url) {
           if (photo.url.startsWith('/CallPhotos')) {
               return 'https://prostarminfosys.sharepoint.com/sites/RemoteCallManagementonline' + photo.url;
           }
           return photo.url;
       }
    }
    return '';
  },

  removePhoto(ticketId, photoId){
    requireAuth();
    const c = this.call(ticketId);
    if(!can('call.update.all') && !ownsCall(c)) throw new Error('Not allowed.');
    
    // Ticket ki list me se photo ka record hata do
    c.photos = (c.photos || []).filter(p => p.id !== photoId);
    
    // PhotoStore.del(photoId); <--- YEH LINE HATA DI GAYI HAI kyunki ab local storage use nahi ho raha
    
    this.audit('PHOTO_REMOVE', ticketId, photoId, '', '');
    Store.save();
  },

  /* ---- login master sync (SharePoint / GitHub) ---- */
  async fetchUserSource(url){
    const u = url || Store.db.config.userSource.url;
    if(!u) throw new Error('No user source URL is configured.');
    const res = await fetch(u, { cache:'no-store', credentials:'include' });
    if(!res.ok) throw new Error('User file returned HTTP ' + res.status + '.');
    if(/\.json(\?|$)/i.test(u) || (res.headers.get('content-type') || '').indexOf('json') >= 0){
      const j = await res.json();
      return Array.isArray(j) ? j : (j.users || []);
    }
    const blob = await res.blob();
    const rows = await readXlsx(blob);
    const head = rows[0].map(h => String(h).trim());
    return rows.slice(1).filter(r => r.some(v => String(v || '').trim()))
      .map(r => { const o = {}; head.forEach((h, i) => o[h] = cleanCell(r[i])); return o; });
  },
  /* One way in for the login master, used by the sign-in screen, the settings
     sync panel and the start-up fetch: read a .xlsx / .csv / .json, take the
     ADMIN / HELPDESK Team / TRCE USER tabs as role membership when they exist,
     and refresh the support-taken master from its tab if the workbook has one. */
  async ingestUserFile(source, label, opts){
    opts = opts || {};
    let rows = [], lists = null, found = [], taken = 0;
    const isBlob = source && typeof source.arrayBuffer === 'function';
    const asObjects = grid => {
      if(!grid || grid.length < 2) return [];
      const head = grid[0].map(h => String(h).trim());
      return grid.slice(1).filter(r => r.some(v => String(v || '').trim()))
        .map(r => { const o = {}; head.forEach((h, i) => o[h] = cleanCell(r[i])); return o; });
    };

    if(!isBlob){                                  // a URL
      rows = await this.fetchUserSource(source);
    } else if(/\.json$/i.test(label || '')){
      const j = JSON.parse(await source.text());
      rows = Array.isArray(j) ? j : (j.users || []);
    } else if(/\.csv$/i.test(label || '')){
      rows = asObjects(csvParse(await source.text()));
    } else {
      rows = asObjects(await readXlsx(source));
      const TABS = { ADMIN:['ADMIN','Admin'], HELPDESK:['HELPDESK Team','HELPDESK','Helpdesk Team'], TRCE:['TRCE USER','TRCE','TRCE Users'] };
      lists = this.roleLists();
      for(const role in TABS){
        for(const nm of TABS[role]){
          const grid = await readXlsx(source, nm);
          if(!grid || grid.length < 2) continue;
          const objs = asObjects(grid);
          const codes = this.roleListFromRows(objs);
          if(codes.length){
            lists[role] = codes;
            found.push(nm + ' (' + codes.length + ')');
            /* the tab carries the people too, so they become logins */
            objs.forEach(o => { if(!rows.some(r => String(r.EmpCode || r['Employee ID'] || '').trim().toUpperCase() === String(o['Employee ID'] || o.EmpCode || '').trim().toUpperCase())) rows.push(o); });
          }
          break;
        }
      }
      /* optional: the recipients master travels in the same workbook */
      const rsg = await readXlsx(source, 'Remote Support Given To');
      if(rsg && rsg.length > 1 && opts.refreshRecipients !== false){
        const objs = asObjects(rsg);
        objs.forEach(o => {
          const id = String(o['Employee ID'] || '').trim(); if(!id) return;
          const ex = Store.db.supportTakenUsers.find(u => u.employeeId === id);
          if(ex){ ex.fullName = o['Full Name'] || ex.fullName; ex.jobTitle = o['Job Title'] || ex.jobTitle; ex.location = o.Location || ex.location; ex.active = true; }
          else Store.db.supportTakenUsers.push({ id:'T' + pad(Store.db.supportTakenUsers.length + 1, 4), employeeId:id,
            fullName:o['Full Name'] || '', dateOfJoining:'', jobTitle:o['Job Title'] || '', department:'Operation',
            subDepartment:'', branch:'', location:o.Location || '', active:true });
          taken++;
        });
      }
    }

    if(!rows.length) throw new Error('No user rows found in ' + (label || 'the user file') + '.');
    const res = this.syncUsers(rows, label || String(source), opts);
    if(lists && found.length){
      try { const rr = this.setRoleLists(lists, Session.user ? Session.user.employeeId : '');
        res.roleNote = 'Roles set from ' + found.join(', ') + ' — ' + rr.logins + ' accounts can sign in.';
      } catch(e){ res.roleNote = 'Role tabs found but not applied: ' + e.message; }
    }
    if(taken) res.recipientNote = taken + ' support recipients refreshed.';
    Store.save();
    return res;
  },
  syncUsers(rows, sourceLabel, opts){
    opts = opts || {};
    const db = Store.db, now = new Date().toISOString();
    const norm = rows.map(r => ({
      code: String(r.EmpCode || r['Employee ID'] || r.employeeId || '').trim().toUpperCase(),
      name: String(r.FullName || r['Full Name'] || r.fullName || '').trim(),
      pw:   String(r.Password || r.password || '').trim(),
      /* a workbook row carries Location ("MH-Mumbai"); branch and zone come from
         the reference directory when the file itself does not supply them */
      loc: String(r.Location || r.location || '').trim(),
      branch: String(r.Branch || '').trim() || String(r.Location || '').trim().replace('-', '_'),
      zone: String(r.Zone || '').trim(),
      desig: String(r.Designation || r['Job Title'] || '').trim(),
      mgr: String(r.ManagerCode || '').trim(), mgrName: String(r.ManagerName || '').trim(),
      xrole: String(r.Role || '').trim().toLowerCase(),
      hash: String(r.PasswordHash || '').trim(), hsalt: String(r.PasswordSalt || '').trim()
    })).filter(r => r.code && r.name);
    if(!norm.length) throw new Error('No usable rows — EmpCode, FullName, Password and Role are required.');
    let created = 0, updated = 0, pwChanged = 0, deactivated = 0;
    const seen = {};
    norm.forEach(r => {
      seen[r.code] = true;
      const ex = db.users.find(u => u.employeeId === r.code);
      if(!ex){ db.users.push(buildUserRecord(r, 'U' + pad(db.users.length + 1, 4), db.config.roleMap, now)); created++; return; }
      let touched = false;
      /* Only fields the file actually carries are overwritten — a user file
         without a Branch column must not wipe the branch we already hold. */
      ['fullName|name','branch|branch','zone|zone','designation|desig','managerCode|mgr','managerName|mgrName','sourceRole|xrole']
        .forEach(pairs => { const [k, v] = pairs.split('|');
          if(r[v] !== undefined && r[v] !== '' && ex[k] !== r[v]){ ex[k] = r[v]; touched = true; } });
      const mapped = db.config.roleMap[r.xrole] || 'TRCE';
      if(!ex.roleOverride && ex.role !== mapped){ ex.role = mapped; touched = true; }
      if(r.hash && r.hsalt && (r.hash !== ex.passwordHash || r.hsalt !== ex.salt)){
        if(ex.pwSource === 'LOCAL' && !opts.forcePassword){ /* changed in the app — left alone */ }
        else { ex.salt = r.hsalt; ex.passwordHash = r.hash; ex.pwSource = 'SYNC'; pwChanged++; touched = true; }
      } else if(r.pw && hashPassword(r.pw, ex.salt) !== ex.passwordHash){
        if(ex.pwSource === 'LOCAL' && !opts.forcePassword){ /* user changed it here — left alone */ }
        else { ex.salt = makeSalt(); ex.passwordHash = hashPassword(r.pw, ex.salt); ex.pwSource = 'SYNC'; pwChanged++; touched = true; }
      }
      if(!ex.active && opts.reactivate !== false){ ex.active = true; touched = true; }
      if(touched){ ex.updatedAt = now; updated++; }
    });
    if(opts.deactivateMissing){
      db.users.forEach(u => { if(!seen[u.employeeId] && u.active){ u.active = false; deactivated++; } });
    }
    /* If every row names one of the three application roles — which is what a
       users.json built from the ADMIN / HELPDESK Team / TRCE USER sheets looks
       like — the file also defines who holds each role. A mixed directory file
       (job titles, branch roles) leaves the lists alone. */
    const MAP = { admin:'ADMIN', helpdesk:'HELPDESK', 'helpdesk team':'HELPDESK', trce:'TRCE', 'trce user':'TRCE' };
    if(norm.length && norm.every(r => MAP[r.xrole])){
      const L = { ADMIN:[], HELPDESK:[], TRCE:[] };
      norm.forEach(r => L[MAP[r.xrole]].push(r.code));
      if(L.ADMIN.length) db.config.roleLists = L;
    }
    applyRoleLists(db);
    db.userSync = { lastSyncAt:now, source:sourceLabel || db.config.userSource.url, count:norm.length };
    this.audit('USER_SYNC', '', '', sourceLabel || 'user source', created + ' new, ' + updated + ' updated, ' + pwChanged + ' passwords, ' + deactivated + ' deactivated');
    Store.save();
    return { read:norm.length, created, updated, pwChanged, deactivated };
  },
  /* Sample tickets for a demo or a training session. Never runs on its own and
     refuses once real tickets exist. */
  sampleCalls(){
    requireAuth(); if(!can('user.manage')) throw new Error('Only an admin can add sample tickets.');
    if(Store.db.calls.length) throw new Error('Sample tickets can only be added to an empty ticket list.');
    if(!Store.db.users.filter(u => u.role === 'TRCE').length) throw new Error('Load the user list first — sample tickets need TRCE users to assign to.');
    seedDemoCalls(Store.db);
    this.audit('SAMPLE_DATA', '', '0 tickets', Store.db.calls.length + ' tickets', 'Demo tickets generated');
    Store.save();
    return Store.db.calls.length;
  },

  /* ---- named role lists (Admin / Helpdesk / TRCE membership) ---- */
  roleLists(){ return JSON.parse(JSON.stringify(Store.db.config.roleLists || { ADMIN:[], HELPDESK:[], TRCE:[] })); },
  saveRoleLists(lists){
    requireAuth(); if(!can('user.manage')) throw new Error('Not allowed.');
    return this.setRoleLists(lists, Session.user.employeeId);
  },
  /* The same work without the permission check, for the very first load —
     the user list has to be able to define its own roles before anyone can
     sign in. Everything else goes through saveRoleLists. */
  setRoleLists(lists, byWhom){
    const clean = {};
    ['ADMIN','HELPDESK','TRCE'].forEach(r => {
      clean[r] = Array.from(new Set((lists[r] || []).map(c => String(c).trim().toUpperCase()).filter(Boolean)));
    });
    /* one person, one role — first list wins, in Admin > Helpdesk > TRCE order */
    const seen = {};
    ['ADMIN','HELPDESK','TRCE'].forEach(r => { clean[r] = clean[r].filter(c => { if(seen[c]) return false; seen[c] = r; return true; }); });
    if(!clean.ADMIN.length) throw new Error('At least one admin is required.');
    const before = Store.db.users.filter(u => u.role).length;
    Store.db.config.roleLists = clean;
    const after = applyRoleLists(Store.db);
    Store.db.audit.unshift({ timestamp:new Date().toISOString(), employeeId:byWhom || 'user list',
      userName:byWhom ? '' : 'User list load', action:'ROLE_LISTS', ticketId:'',
      oldValue:String(before) + ' with a login', newValue:String(after) + ' with a login',
      remarks:'Admin ' + clean.ADMIN.length + ' · Helpdesk ' + clean.HELPDESK.length + ' · TRCE ' + clean.TRCE.length });
    Store.save();
    return { admin:clean.ADMIN.length, helpdesk:clean.HELPDESK.length, trce:clean.TRCE.length, logins:after };
  },
  /* Accepts rows from a sheet named TRCE USER / HELPDESK Team / ADMIN */
  roleListFromRows(rows){
    return rows.map(r => String(r.EmpCode || r['Employee ID'] || r.employeeId || r.Code || '').trim().toUpperCase()).filter(Boolean);
  },

  saveRolePerms(map){
    requireAuth(); if(!can('user.manage')) throw new Error('Not allowed.');
    Store.db.config.rolePerms = map;
    Store.db.users.forEach(u => { u.role = effectiveRole(u); });
    this.audit('ROLE_PERMS', '', '', 'permission matrix updated', '');
    Store.save();
  },
  setUserRole(employeeId, role){
    requireAuth(); if(!can('user.manage')) throw new Error('Not allowed.');
    const u = Store.db.users.find(x => x.employeeId === employeeId);
    if(!u) throw new Error('User not found.');
    const old = u.role;
    u.roleOverride = role; u.role = role; u.updatedAt = new Date().toISOString();
    this.audit('USER_ROLE', '', old, role, employeeId);
    Store.save();
  },

  saveAsset(a, isNew){
    requireAuth(); if(!can('master.manage')) throw new Error('Only the HD team can change master data.');
    const code = String(a.itemCode || '').trim();
    if(!code || !String(a.itemName || '').trim()) throw new Error('Item Code and Item Name are required.');
    const dup = Store.db.assets.find(x => x.itemCode.toLowerCase() === code.toLowerCase() && x.id !== a.id);
    if(dup) throw new Error('Item Code ' + code + ' already exists in the asset master.');
    if(isNew){ a.id = 'A' + pad(Store.db.assets.length + 1, 5); Store.db.assets.push(a); }
    else { const i = Store.db.assets.findIndex(x => x.id === a.id); Store.db.assets[i] = a; }
    this.audit(isNew ? 'ASSET_CREATE' : 'ASSET_UPDATE', '', '', code, a.itemName);
    Store.save();
  },
  saveSupportTakenUser(u, isNew){
    requireAuth(); if(!can('master.manage')) throw new Error('Only the HD team can change master data.');
    const id = String(u.employeeId || '').trim().toUpperCase();
    if(!id || !String(u.fullName || '').trim()) throw new Error('Employee ID and Full Name are required.');
    const dup = Store.db.supportTakenUsers.find(x => x.employeeId.toUpperCase() === id && x.id !== u.id);
    if(dup) throw new Error('Employee ID ' + id + ' already exists in this master.');
    u.employeeId = id;
    if(isNew){ u.id = 'T' + pad(Store.db.supportTakenUsers.length + 1, 4); Store.db.supportTakenUsers.push(u); }
    else { const i = Store.db.supportTakenUsers.findIndex(x => x.id === u.id); Store.db.supportTakenUsers[i] = u; }
    this.audit(isNew ? 'STU_CREATE' : 'STU_UPDATE', '', '', id, u.fullName);
    Store.save();
  },
  saveUser(u, isNew, password){
    requireAuth(); if(!can('user.manage')) throw new Error('Only the HD team can manage users.');
    const id = String(u.employeeId || '').trim().toUpperCase();
    if(!id || !String(u.fullName || '').trim()) throw new Error('Employee ID and Full Name are required.');
    const dup = Store.db.users.find(x => x.employeeId.toUpperCase() === id && x.id !== u.id);
    if(dup) throw new Error('Employee ID ' + id + ' already has a login.');
    u.employeeId = id; u.updatedAt = new Date().toISOString();
    if(isNew){
      u.id = 'U' + pad(Store.db.users.length + 1, 4); u.createdAt = u.updatedAt;
      u.salt = makeSalt(); u.passwordHash = hashPassword(password || DEFAULT_PW, u.salt); u.mustChange = true;
      Store.db.users.push(u);
    } else {
      const i = Store.db.users.findIndex(x => x.id === u.id);
      u.salt = Store.db.users[i].salt; u.passwordHash = Store.db.users[i].passwordHash; u.mustChange = Store.db.users[i].mustChange;
      Store.db.users[i] = u;
    }
    this.audit(isNew ? 'USER_CREATE' : 'USER_UPDATE', '', '', id, u.role + ' / ' + (u.active ? 'active' : 'inactive'));
    Store.save();
  },
  resetPassword(employeeId){
    requireAuth(); if(!can('user.manage')) throw new Error('Only the HD team can reset passwords.');
    const u = Store.db.users.find(x => x.employeeId === employeeId);
    u.salt = makeSalt(); u.passwordHash = hashPassword(DEFAULT_PW, u.salt); u.mustChange = true;
    this.audit('PASSWORD_RESET', '', '', employeeId, 'Reset to default');
    Store.save();
  },

  /* ---- import ---- */
  importRows(kind, rows){
    requireAuth(); if(!can('master.import')) throw new Error('Only the HD team can import master data.');
    let created = 0, updated = 0;
    rows.forEach(r => {
      if(kind === 'assets'){
        const ex = Store.db.assets.find(a => a.itemCode.toLowerCase() === r.itemCode.toLowerCase());
        if(ex){ Object.assign(ex, r); updated++; }
        else { r.id = 'A' + pad(Store.db.assets.length + 1, 5); r.active = true; Store.db.assets.push(r); created++; }
      } else if(kind === 'users'){
        const ex = Store.db.users.find(u => u.employeeId.toUpperCase() === r.employeeId.toUpperCase());
        if(ex){ ex.fullName = r.fullName; ex.department = r.department; ex.location = r.location; ex.updatedAt = new Date().toISOString(); updated++; }
        else {
          const s = makeSalt();
          Store.db.users.push({ id:'U' + pad(Store.db.users.length + 1, 4), employeeId:r.employeeId.toUpperCase(), fullName:r.fullName,
            department:r.department, location:r.location, role:'REMOTE_SUPPORT', salt:s, passwordHash:hashPassword(DEFAULT_PW, s),
            mustChange:true, active:true, createdAt:new Date().toISOString(), updatedAt:new Date().toISOString() });
          created++;
        }
      } else {
        const ex = Store.db.supportTakenUsers.find(u => u.employeeId.toUpperCase() === r.employeeId.toUpperCase());
        if(ex){ Object.assign(ex, r, { id:ex.id, active:true }); updated++; }
        else { r.id = 'T' + pad(Store.db.supportTakenUsers.length + 1, 4); r.active = true; Store.db.supportTakenUsers.push(r); created++; }
      }
    });
    this.audit('IMPORT', '', '', kind, created + ' new, ' + updated + ' updated');
    Store.save();
    return { created, updated };
  },

  /* ---- config ---- */
  saveConfig(cfg){
    requireAuth(); if(!can('settings')) throw new Error('Not allowed.');
    Object.assign(Store.db.config, cfg);
    this.audit('CONFIG_UPDATE', '', '', 'settings', '');
    Store.save();
  }
};

/* ============================================================
   6. EXPORT — exact Data Capture Format(2).xlsx column order
   ============================================================ */
const CAPTURE_COLUMNS = ['Sr No','Ticket ID','Ticket Raise Date','Remote Support Assigned - Emp ID','Remote Support Assigned - Emp Name',
  'Customer Name','Customer Segment','Item Group','OEM','Item Name','Item Code','Product Phase','Issue Reported','Support Type',
  'Remote Support Given To (ID)','Remote Support Given To (Name)','Supportive Engineer - ID','Supportive Engineer - Name',
  'Corrective Action Taken','Spare Required','Spare Name','Call Status','Ticket Updation Date','Ticket Re-Open Date',
  'TAT Slab'];   /* 25th column — added on top of the supplied template */

function productOf(c){
  if(c.productSelectionType === 'OTHER' && c.otherProduct)
    return { group:c.otherProduct.itemGroup || '', oem:c.otherProduct.oem || '', name:c.otherProduct.itemName || '', code:c.otherProduct.itemCode || '' };
  return { group:c.itemGroup || '', oem:c.oem || '', name:c.itemName || '', code:c.itemCode || '' };
}
function captureRow(c, sr){
  const p = productOf(c);
  const gid = c.recipientType === 'DIRECT_CUSTOMER' ? 'Direct Customer' : (c.givenToId || '');
  const gnm = c.recipientType === 'DIRECT_CUSTOMER' ? 'Direct Customer' : (c.givenToName || '');
  return [sr, c.ticketId, fmtDT(c.ticketRaiseDate), c.assignedEmpId, c.assignedEmpName, c.customerName, c.customerSegment,
    p.group, p.oem, p.name, p.code, c.productPhase, c.issueReported, c.supportType || '', gid, gnm,
    c.supportEngineerId || '', c.supportEngineerName || '', c.correctiveAction || '', c.spareRequired || '', c.spareName || '',
    c.callStatus, c.ticketUpdationDate ? fmtDT(c.ticketUpdationDate) : '', c.reopenDate ? fmtDT(c.reopenDate) : '',
    c.tatSlab || ''];
}
function exportCalls(calls, format, label){
  const rows = calls.map((c, i) => captureRow(c, i + 1));
  const stamp = ymd().replace(/-/g, '') + '-' + pad(new Date().getHours(), 2) + pad(new Date().getMinutes(), 2);
  const name = 'Data_Capture_' + (label || 'Calls') + '_' + stamp;
  if(format === 'csv') download(name + '.csv', new Blob([csvBuild(CAPTURE_COLUMNS, rows)], { type:'text/csv;charset=utf-8' }));
  else download(name + '.xlsx', xlsxBlob('Data Down Load Form', CAPTURE_COLUMNS, rows));
  API.audit('EXPORT', '', '', label || 'calls', calls.length + ' rows / ' + (format || 'xlsx'));
  toast(calls.length + ' ticket' + (calls.length === 1 ? '' : 's') + ' exported.', 'ok');
}
function exportGeneric(name, headers, rows, format){
  const stamp = ymd().replace(/-/g, '');
  if(format === 'csv') download(name + '_' + stamp + '.csv', new Blob([csvBuild(headers, rows)], { type:'text/csv;charset=utf-8' }));
  else download(name + '_' + stamp + '.xlsx', xlsxBlob(name.slice(0, 31), headers, rows));
  API.audit('EXPORT', '', '', name, rows.length + ' rows');
  toast('Export ready.', 'ok');
}

/* ===== p5_views1.js ===== */
/* ============================================================
   7. NAVIGATION + ROUTER
   ============================================================ */
const NAV = [
  { group:'' , items:[ { k:'dashboard', t:'Dashboard' } ] },
  { group:'Calls', items:[
      { k:'calls', t:'All calls', perm:'call.view.all' },
      { k:'mycalls', t:'My calls' },
      { k:'newcall', t:'New call' },
      { k:'updates', t:'Call updates' }
  ]},
  { group:'Analysis', items:[
      { k:'supporttaken', t:'Support taken' },
      { k:'reports', t:'Reports' },
      { k:'export', t:'Export' }
  ]},
  { group:'Masters', items:[
      { k:'assets', t:'Asset master' },
      { k:'rsusers', t:'Remote support users' },
      { k:'stusers', t:'Support taken users' }
  ]},
  { group:'Administration', items:[
      { k:'users', t:'User & role management', perm:'user.manage' },
      { k:'audit', t:'Audit log', perm:'audit.view' },
      { k:'settings', t:'Settings', perm:'settings' }
  ]},
  { items:[ { k:'logout', t:'Sign out' } ] }
];
const TITLES = { dashboard:'Dashboard', calls:'All calls', mycalls:'My calls', newcall:'Log a new call', updates:'Call updates',
  supporttaken:'Support taken', reports:'Reports', export:'Export', assets:'Asset master', rsusers:'Remote support user master',
  stusers:'Support taken user master', users:'User & role management', audit:'Audit log', settings:'Settings' };
const CRUMBS = { dashboard:'Overview of the remote support desk', calls:'Every ticket in the system', mycalls:'Tickets assigned to or created by you',
  newcall:'Ticket details are captured from the call logged form', updates:'Tickets waiting for your update',
  supporttaken:'Who received remote support', reports:'Call, support taken and other-product reports', export:'Standard data capture format',
  assets:'Item group, OEM, item name and item code', rsusers:'Users who own and handle calls', stusers:'Users who receive remote support',
  users:'Logins, roles and status', audit:'Every action recorded', settings:'Dropdown values and data' };

let currentView = 'dashboard';
function buildNav(){
  const nav = $('#sbNav'); nav.innerHTML = '';
  NAV.forEach(sec => {
    const items = sec.items.filter(i => !i.perm || can(i.perm));
    if(!items.length) return;
    if(sec.group){ const g = document.createElement('div'); g.className = 'sb-group'; g.textContent = sec.group; nav.appendChild(g); }
    items.forEach(i => {
      const b = document.createElement('button');
      b.className = 'sb-link' + (i.k === currentView ? ' active' : '');
      b.dataset.k = i.k;
      b.innerHTML = '<span>' + esc(i.t) + '</span>';
      if(i.k === 'mycalls' || i.k === 'updates'){
        const n = i.k === 'mycalls'
          ? API.calls(c => c.assignedEmpId === Session.user.employeeId).length
          : API.calls(c => OPEN_STATUSES.indexOf(c.callStatus) >= 0 && (can('call.view.all') || c.assignedEmpId === Session.user.employeeId)).length;
        if(n) b.innerHTML += '<span class="cnt num">' + n + '</span>';
      }
      b.onclick = () => go(i.k);
      nav.appendChild(b);
    });
  });
}
function go(view, params){
  if(view === 'logout'){
    confirmDlg('Sign out', 'You will be returned to the sign-in screen.', () => { API.logout(); location.href = 'login.html'; }, 'Sign out');
    return;
  }
  if(!VIEWS[view]) view = 'dashboard';
  currentView = view;
  Session.touch();
  $('#pgTitle').textContent = TITLES[view] || view;
  $('#pgCrumb').textContent = CRUMBS[view] || '';
  $('#sidebar').classList.remove('open');
  const scrim = $('.scrim'); if(scrim) scrim.remove();
  buildNav();
  /* Views attach delegated click handlers to #page. Swapping in a fresh
     element on every navigation drops the old listeners, so revisiting a
     screen cannot fire the same handler twice. */
  const stale = $('#page');
  const page = stale.cloneNode(false);
  stale.replaceWith(page);
  try { (VIEWS[view] || VIEWS.dashboard)(page, params || {}); }
  catch(e){ page.innerHTML = '<div class="card"><div class="card-b"><div class="note warn">' + esc(e.message) + '</div></div></div>'; }
  window.scrollTo(0, 0);
}
const VIEWS = {};

/* ---------- shared bits ---------- */
function statusBadge(s){ return '<span class="bdg ' + (STATUS_CLASS[s] || 'tone-n') + '">' + esc(s) + '</span>'; }
function recipientLabel(c){
  if(!c.supportType) return '<span class="mut">—</span>';
  if(c.supportType === 'Own Visit with Support Engineer')
    return esc(c.supportEngineerName || '—') + '<span class="cellsub">Engineer ' + esc(c.supportEngineerId || '') + '</span>';
  if(c.recipientType === 'DIRECT_CUSTOMER') return '<span class="bdg tone-a">Direct customer</span>';
  if(c.recipientType === 'OTHER_USER') return esc(c.givenToName) + '<span class="cellsub">Other user · ' + esc(c.givenToId || 'no ID') + '</span>';
  return esc(c.givenToName || '—') + (c.givenToId ? '<span class="cellsub">' + esc(c.givenToId) + '</span>' : '');
}
function productLabel(c){
  const p = productOf(c);
  return esc(p.name || '—') + '<span class="cellsub">' + esc([p.code, p.oem || 'OEM n/a'].filter(Boolean).join(' · ')) +
    (c.productSelectionType === 'OTHER' ? ' · <b style="color:#8A5406">other product</b>' : '') + '</span>';
}

/* ============================================================
   8. DASHBOARD — CRM style: performance first, then breakdowns
   ============================================================ */
VIEWS.dashboard = function(page){
  const hd = can('call.view.all');
  const all = API.calls();
  const rows = hd ? all : all.filter(c => c.assignedEmpId === Session.user.employeeId);
  const now = new Date(), today = ymd(), thisMonth = ym(now);
  const lastMonth = ym(new Date(now.getFullYear(), now.getMonth() - 1, 1));
  const by = st => rows.filter(c => c.callStatus === st).length;
  const isOpen = c => OPEN_STATUSES.indexOf(c.callStatus) >= 0;
  const days = (a, b) => Math.max(0, (new Date(b || Date.now()) - new Date(a)) / 86400000);
  const hrs  = (a, b) => Math.max(0, (new Date(b || Date.now()) - new Date(a)) / 3600000);
  const pct = (a, b) => b ? Math.round(a * 1000 / b) / 10 : 0;

  const open = rows.filter(isOpen);
  const monthRows = rows.filter(c => ym(c.ticketRaiseDate) === thisMonth);
  const prevRows  = rows.filter(c => ym(c.ticketRaiseDate) === lastMonth);
  const settled = rows.filter(c => ['Resolved','Closed'].indexOf(c.callStatus) >= 0);
  const closedTimes = settled.filter(c => c.ticketUpdationDate).map(c => days(c.ticketRaiseDate, c.ticketUpdationDate));
  const avgDays = closedTimes.length ? (closedTimes.reduce((a, b) => a + b, 0) / closedTimes.length) : 0;
  const reopened = rows.filter(c => c.reopenDate).length;
  const aged = open.filter(c => days(c.ticketRaiseDate) > 7).length;
  const delta = (a, b) => b === 0 ? (a ? '+100%' : '0%') : (a - b >= 0 ? '+' : '') + Math.round((a - b) * 100 / b) + '%';

  const hero = (lbl, val, sub, trend, tone, filter) =>
    '<div class="hero-k' + (filter !== undefined ? ' click' : '') + '" data-f="' + esc(filter || '') + '">' +
      '<div class="lbl">' + esc(lbl) + '</div>' +
      '<div class="val num">' + val + (trend ? '<span class="trend ' + tone + '">' + esc(trend) + '</span>' : '') + '</div>' +
      '<div class="sub">' + esc(sub) + '</div></div>';

  let h = '<div class="hero">' +
    hero('Open tickets', open.length, aged + ' older than 7 days', '', '', 'OPEN') +
    hero('Logged this month', monthRows.length, MONTHS[now.getMonth()] + ' · ' + prevRows.length + ' last month',
         delta(monthRows.length, prevRows.length), monthRows.length >= prevRows.length ? 'up' : 'dn') +
    hero('Resolution rate', pct(settled.length, rows.length) + '%', settled.length + ' of ' + rows.length + ' resolved or closed') +
    hero('Avg time to resolve', (Math.round(avgDays * 10) / 10) + 'd', 'first log to latest update') +
    hero('Reopen rate', pct(reopened, rows.length) + '%', reopened + ' ticket' + (reopened === 1 ? '' : 's') + ' came back', '', '', 'Reopened') +
    '</div>';

  /* Pipeline: a proportional band across the top so the shape of the queue
     reads at a glance, then one equal card per stage, all on a single row. */
  const stages = [['New','#1D4ED8'],['Assigned','#0066B3'],['In Progress','#069EDB'],
    ['Pending Customer Shutdown / Update','#E08A00'],['Pending Spare','#E08A00'],['Hold','#7A4FD6'],
    ['Resolved','#0B8A5C'],
    ['Remote Support Closed but Engineer Required to Visit for further Assessment','#075E85'],
    ['Closed','#44586B'],['Reopened','#D81E26']];
  const stageN = stages.map(s => by(s[0]));
  const total = rows.length || 1;
  const openN = rows.filter(isOpen).length;
  const share = n => Math.round(n * 100 / total);

  h += '<div class="card"><div class="card-h"><h3>Call pipeline</h3><span class="spacer"></span>' +
    '<span class="mut sm">' + openN + ' open of ' + rows.length + ' · click a stage to filter</span></div><div class="card-b">' +
    '<div class="pipe-band">' + stages.map((s, i) => stageN[i]
        ? '<i style="flex:' + stageN[i] + ';background:' + s[1] + '" title="' + esc(s[0]) + ': ' + stageN[i] + '"></i>' : '').join('') +
    '</div>' +
    '<div class="pipe one-row">' + stages.map((s, i) => {
      const n = stageN[i];
      return '<button class="pipe-s' + (n ? '' : ' zero') + '" data-f="' + esc(s[0]) + '" style="--c:' + s[1] + '" title="' + esc(s[0]) + '">' +
        '<span class="hd"><i class="dot"></i><span class="t">' + esc(shortStatus(s[0])) + '</span></span>' +
        '<span class="n num">' + n + '</span>' +
        '<span class="p num">' + (n ? share(n) + '%' : '—') + '</span></button>';
    }).join('') + '</div></div></div>';

  /* Open ticket ageing — days, or the same open tickets broken down by branch
     or by TRCE user for the desk roles. */
  function ageingView(mode){
    if(mode === 'branch' || mode === 'trce'){
      const key = mode === 'branch'
        ? c => (userOf(c.assignedEmpId).branch || '—').replace('_', ' ')
        : c => { const u = userOf(c.assignedEmpId); return (u.employeeId || '—') + (u.fullName ? ' · ' + u.fullName : ''); };
      const m = {};
      open.forEach(c => { const k = key(c) || '—';
        if(!m[k]) m[k] = { k, v:0, old:0, oldest:0 };
        const t = hrs(c.ticketRaiseDate);
        m[k].v++; if(t > 168) m[k].old++; if(t > m[k].oldest) m[k].oldest = t; });
      const list = Object.keys(m).map(k => m[k]).sort((a, b) => b.old - a.old || b.v - a.v);
      if(!list.length) return '<div class="empty"><b>Nothing open</b><span>No open tickets to age.</span></div>';
      return '<table class="tbl"><thead><tr><th>' + (mode === 'branch' ? 'Branch' : 'TRCE user') +
        '</th><th class="r">Open</th><th class="r">Over 7 days</th><th class="r">Oldest</th><th style="width:22%"></th></tr></thead><tbody>' +
        list.map(r => '<tr><td>' + esc(r.k) + '</td><td class="r num">' + r.v + '</td>' +
          '<td class="r num' + (r.old ? ' warn-t' : '') + '">' + r.old + '</td>' +
          '<td class="r num mut">' + ageLabel(r.oldest) + '</td>' +
          '<td><span class="minibar"><i style="width:' + Math.round(r.v * 100 / list[0].v) + '%"></i></span></td></tr>').join('') +
        '</tbody></table>';
    }
    const sameDay = open.filter(c => hrs(c.ticketRaiseDate) < 24).length;
    const oldest = open.length ? Math.max.apply(null, open.map(c => hrs(c.ticketRaiseDate))) : 0;
    return hbars(bands.map(b => ({ k:b[0], v:open.filter(b[1]).length, c:b[2] }))) +
      '<div class="note ' + (aged ? 'warn' : 'info') + '" style="margin-top:14px">' +
      sameDay + ' logged in the last 24 hours · ' +
      (aged ? aged + ' past seven days' : 'nothing past seven days') +
      (open.length ? ' · oldest ' + ageLabel(oldest) : '') + '</div>';
  }

  const cnt = (arr, keyFn) => { const m = {}; arr.forEach(x => { const k = keyFn(x) || '—'; m[k] = (m[k] || 0) + 1; });
    return Object.keys(m).map(k => ({ k, v:m[k] })).sort((a, b) => b.v - a.v); };
  const userOf = id => Store.db.users.find(u => u.employeeId === id) || {};

  /* trend: logged vs closed */
  const labels = [], logged = [], closed = [];
  for(let i = 11; i >= 0; i--){
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1), key = ym(d);
    labels.push(MONTHS[d.getMonth()] + (d.getMonth() === 0 ? " '" + String(d.getFullYear()).slice(2) : ''));
    logged.push(rows.filter(c => ym(c.ticketRaiseDate) === key).length);
    closed.push(rows.filter(c => c.ticketUpdationDate && ym(c.ticketUpdationDate) === key && ['Resolved','Closed'].indexOf(c.callStatus) >= 0).length);
  }

  /* ageing of open tickets */
  /* Ageing starts in hours, because a same-day queue is where the desk acts,
     and only widens to days once a ticket is past its first working day. */
  const band = (lo, hi) => c => { const t = hrs(c.ticketRaiseDate); return t >= lo && (hi === null || t < hi); };
  const bands = [
    ['0–2 Hrs',    band(0, 2),      '#0B8A5C'],
    ['2–4 Hrs',    band(2, 4),      '#12A06B'],
    ['4–6 Hrs',    band(4, 6),      '#069EDB'],
    ['6–8 Hrs',    band(6, 8),      '#0066B3'],
    ['8–24 Hrs',   band(8, 24),     '#004E8C'],
    ['1–2 Days',   band(24, 72),    '#E08A00'],
    ['3–7 Days',   band(72, 168),   '#C2410C'],
    ['Over 7 Days',band(168, null), '#D81E26']];

  h += '<div class="dgrid">' +
    '<div class="card"><div class="card-h"><h3>Logged vs resolved</h3><span class="spacer"></span><span class="mut sm">last 12 months</span></div><div class="card-b">' +
      multiLine(labels, [{ name:'Logged', values:logged, color:'#0066B3', area:true }, { name:'Resolved / closed', values:closed, color:'#0B8A5C', dash:true }]) + '</div></div>' +
    '<div class="card" id="ageCard"><div class="card-h"><h3>Open ticket ageing</h3><span class="spacer"></span>' +
      (hd ? '<div class="seg sm" id="ageSeg"><button data-a="band" class="on">Ageing</button>' +
            '<button data-a="branch">Branch</button><button data-a="trce">TRCE</button></div>'
          : '<span class="mut sm">' + open.length + ' open</span>') +
      '</div><div class="card-b scroll" id="ageBody"></div></div>' +

    '<div class="card"><div class="card-h"><h3>Status split</h3></div><div class="card-b">' +
      donut(Store.db.config.callStatuses.map(s => ({ k:s, v:by(s) })).filter(d => d.v), { centerLabel:'tickets', compact:true }) + '</div></div>' +

    '<div class="card"><div class="card-h"><h3>ATM vs Non ATM</h3></div><div class="card-b">' +
      donut([{ k:'ATM', v:rows.filter(c => c.customerSegment === 'ATM').length, c:'#0066B3' },
             { k:'Non ATM', v:rows.filter(c => c.customerSegment === 'Non ATM').length, c:'#7A4FD6' }], { centerLabel:'segment', compact:true }) +
      '<div class="mut sm" style="margin:16px 0 6px">Top customers</div>' + hbars(cnt(rows, c => c.customerName).slice(0, 6)) + '</div></div>' +

    '<div class="card"><div class="card-h"><h3>Support channel</h3></div><div class="card-b">' +
      donut([{ k:'Remote support', v:rows.filter(c => c.supportType === 'Remote Support').length, c:'#0066B3' },
             { k:'Own visit', v:rows.filter(c => c.supportType === 'Own Visit').length, c:'#069EDB' },
             { k:'Own visit with engineer', v:rows.filter(c => c.supportType === 'Own Visit with Support Engineer').length, c:'#D81E26' }],
             { centerLabel:'updated', compact:true }) +
      '<div class="mut sm" style="margin:16px 0 6px">Who received it</div>' + hbars([
        { k:'Support taken master', v:rows.filter(c => c.recipientType === 'MASTER_USER').length, c:'#0066B3' },
        { k:'Direct customer', v:rows.filter(c => c.recipientType === 'DIRECT_CUSTOMER').length, c:'#069EDB' },
        { k:'Other / manual', v:rows.filter(c => c.recipientType === 'OTHER_USER').length, c:'#7A4FD6' }]) + '</div></div>' +

    '<div class="card"><div class="card-h"><h3>Product mix</h3><span class="spacer"></span><span class="mut sm">by item group</span></div><div class="card-b">' +
      hbars(cnt(rows, c => productOf(c).group).slice(0, 7)) +
      '<div class="mut sm" style="margin:16px 0 6px">By OEM</div>' + hbars(cnt(rows, c => productOf(c).oem || 'OEM not recorded').slice(0, 4), {}) + '</div></div>';

  /* zone / branch performance — comes from the login master */
  if(hd){
    const zones = cnt(rows, c => userOf(c.assignedEmpId).zone || '—');
    h += '<div class="card"><div class="card-h"><h3>Zone performance</h3><span class="spacer"></span><span class="mut sm">by owner zone</span></div>' +
      '<div class="card-b scroll" style="padding:0"><table class="tbl"><thead><tr><th>Zone</th><th class="r">Logged</th><th class="r">Open</th>' +
      '<th class="r">Closed</th><th class="r">Reopened</th><th class="r">Avg days</th></tr></thead><tbody>' +
      zones.map(z => {
        const zr = rows.filter(c => (userOf(c.assignedEmpId).zone || '—') === z.k);
        const zt = zr.filter(c => c.ticketUpdationDate && ['Resolved','Closed'].indexOf(c.callStatus) >= 0).map(c => days(c.ticketRaiseDate, c.ticketUpdationDate));
        return '<tr><td><b>' + esc(z.k) + '</b></td><td class="r num">' + zr.length + '</td>' +
          '<td class="r num">' + zr.filter(isOpen).length + '</td>' +
          '<td class="r num">' + zr.filter(c => c.callStatus === 'Closed').length + '</td>' +
          '<td class="r num">' + zr.filter(c => c.reopenDate).length + '</td>' +
          '<td class="r num">' + (zt.length ? (Math.round(zt.reduce((a, b) => a + b, 0) / zt.length * 10) / 10) : '—') + '</td></tr>';
      }).join('') + '</tbody></table></div></div>';

    const perf = cnt(rows, c => c.assignedEmpId).slice(0, 8).map(u => {
      const ur = rows.filter(c => c.assignedEmpId === u.k), usr = userOf(u.k);
      return { id:u.k, name:usr.fullName || u.k, branch:usr.branch || '', total:ur.length,
               done:ur.filter(c => ['Resolved','Closed'].indexOf(c.callStatus) >= 0).length, open:ur.filter(isOpen).length };
    }).sort((a, b) => b.done - a.done);
    h += '<div class="card"><div class="card-h"><h3>Top handlers</h3><span class="spacer"></span><span class="mut sm">resolved or closed</span></div>' +
      '<div class="card-b scroll"><div class="lead">' + perf.map((p, i) =>
        '<div class="lead-r"><span class="rk">' + (i + 1) + '</span><span class="av">' + esc(initials(p.name)) + '</span>' +
        '<span class="who"><b>' + esc(p.name) + '</b><span class="mut sm">' + esc(p.id + (p.branch ? ' · ' + p.branch.replace("_", " ") : '')) + '</span></span>' +
        '<span class="st num">' + p.done + '<small>done</small></span><span class="st num">' + p.open + '<small>open</small></span></div>').join('') +
      '</div></div></div>';
  }
  h += '</div>';

  /* activity feed + latest tickets */
  const feed = Store.db.history.slice(-14).reverse()
    .filter(x => hd || rows.some(c => c.ticketId === x.ticketId)).slice(0, 8);
  h += '<div class="dgrid tall" style="margin-top:12px">' +
    '<div class="card" style="grid-column:span 2"><div class="card-h"><h3>' + (hd ? 'Latest tickets' : 'My latest tickets') +
      '</h3><span class="spacer"></span><button class="btn sm" id="dbAll">Open full list</button></div><div id="dbTbl" class="scroll"></div></div>' +
    '<div class="card"><div class="card-h"><h3>Recent activity</h3></div><div class="card-b scroll">' +
      (feed.length ? '<div class="feed">' + feed.map(f =>
        '<div class="feed-i"><span class="dot ' + (f.action === 'REOPENED' ? 'r' : f.action === 'CREATED' ? 'b' : 'g') + '"></span>' +
        '<div><b>' + esc(f.action.replace("_", " ").toLowerCase()) + '</b> · <span class="tid">' + esc(f.ticketId) + '</span>' +
        '<div class="mut sm">' + esc(f.newValue || f.remarks || '') + '</div>' +
        '<div class="mut sm">' + esc(f.performedBy) + ' · ' + fmtDT(f.performedAt) + '</div></div></div>').join('') + '</div>'
        : '<div class="empty">No activity yet</div>') + '</div></div>' +
    '</div>';

  page.innerHTML = h;

  const jump = f => go(hd ? 'calls' : 'mycalls', f ? (f === 'OPEN' ? { open:1 } : { status:f }) : {});
  $$('.hero-k.click', page).forEach(k => k.onclick = () => jump(k.dataset.f));
  $$('.pipe-s', page).forEach(b => b.onclick = () => jump(b.dataset.f));
  /* ageing card: render and wire its Ageing / Branch / TRCE switch */
  const ageBody = $('#ageBody');
  if(ageBody){
    ageBody.innerHTML = ageingView('band');
    const seg = $('#ageSeg');
    if(seg) seg.onclick = e => {
      const b = e.target.closest('button[data-a]'); if(!b) return;
      seg.querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b));
      ageBody.innerHTML = ageingView(b.dataset.a);
    };
  }
  $('#dbAll').onclick = () => jump('');
  DataTable($('#dbTbl'), {
    rows: rows.slice(0, 8), size: 8,
    cols: [
      { key:'ticketId', label:'Ticket', nowrap:true, render:c => '<span class="tid">' + esc(c.ticketId) + '</span><span class="cellsub">' + fmtDate(c.ticketRaiseDate) + '</span>' },
      { key:'customerName', label:'Customer', render:c => esc(c.customerName) + '<span class="cellsub">' + esc(c.customerSegment) + '</span>' },
      { key:'itemName', label:'Product', render:productLabel },
      { key:'assignedEmpName', label:'Owner', render:c => esc(c.assignedEmpName) + '<span class="cellsub">' + esc(c.assignedEmpId + ' · ' + (userOf(c.assignedEmpId).branch || '').replace('_', ' ')) + '</span>' },
      { key:'callStatus', label:'Status', nowrap:true, render:c => statusBadge(c.callStatus) }
    ],
    onRow: c => openCall(c.ticketId),
    emptyTitle:'No tickets yet', emptyText:'Log your first call from the sidebar.'
  });
};

/* ============================================================
   9. CALL LISTS
   ============================================================ */
function callListView(page, params, scope){
  const state = { q:'', status:params.status || '', segment:'', group:'', assignee:'', supportType:'', recipient:'', spare:'', from:'', to:'', ptype:'', openOnly:!!params.open };
  const base = () => scope === 'mine'
    ? API.calls(c => c.assignedEmpId === Session.user.employeeId || c.createdBy === Session.user.employeeId)
    : API.calls();

  page.innerHTML = '<div class="card"><div class="toolbar" id="tb"></div><div class="chips hide" id="chips"></div><div id="tbl"></div></div>';
  const tb = $('#tb', page);
  const cfg = Store.db.config;
  const opt = (arr, sel) => ['<option value="">All</option>'].concat(arr.map(v => '<option' + (v === sel ? ' selected' : '') + '>' + esc(v) + '</option>')).join('');
  tb.innerHTML =
    '<div class="f grow"><label>Search</label><input class="inp" id="fq" placeholder="Ticket, customer, product, issue, engineer…"></div>' +
    '<div class="f"><label>Status</label><select class="inp" id="fst">' + opt(cfg.callStatuses, state.status) + '</select></div>' +
    '<div class="f"><label>Segment</label><select class="inp" id="fsg">' + opt(cfg.customerSegments) + '</select></div>' +
    '<div class="f"><label>Item group</label><select class="inp" id="fgr">' + opt(Array.from(new Set(Store.db.assets.map(a => a.itemGroup))).sort()) + '</select></div>' +
    (scope === 'all' ? '<div class="f"><label>Assigned to</label><select class="inp" id="fas">' + opt(API.activeUsers().map(u => u.employeeId + ' – ' + u.fullName)) + '</select></div>' : '') +
    '<div class="f"><label>Support type</label><select class="inp" id="fsp">' + opt(cfg.supportTypes) + '</select></div>' +
    '<div class="f"><label>Recipient</label><select class="inp" id="frc"><option value="">All</option><option value="MASTER_USER">Master user</option><option value="DIRECT_CUSTOMER">Direct customer</option><option value="OTHER_USER">Other user</option></select></div>' +
    '<div class="f"><label>Product type</label><select class="inp" id="fpt"><option value="">All</option><option value="MASTER">Master product</option><option value="OTHER">Other product</option></select></div>' +
    '<div class="f"><label>Spare</label><select class="inp" id="fspa"><option value="">All</option><option>Yes</option><option>No</option></select></div>' +
    '<div class="f"><label>From</label><input type="date" class="inp" id="ffr"></div>' +
    '<div class="f"><label>To</label><input type="date" class="inp" id="fto"></div>' +
    '<div class="f" style="min-width:auto"><label>&nbsp;</label><div class="btn-row"><button class="btn" id="fclr">Clear</button>' +
    '<button class="btn" id="fexp">Export view</button></div></div>';

  function apply(){
    const q = state.q.toLowerCase().split(/\s+/).filter(Boolean);
    let rows = base().filter(c => {
      if(state.openOnly && OPEN_STATUSES.indexOf(c.callStatus) < 0) return false;
      if(state.status){
        if(state.status === 'Pending'){ if(c.callStatus.indexOf('Pending') !== 0) return false; }
        else if(c.callStatus !== state.status) return false;
      }
      if(state.segment && c.customerSegment !== state.segment) return false;
      if(state.group && productOf(c).group !== state.group) return false;
      if(state.assignee && (c.assignedEmpId + ' – ' + c.assignedEmpName) !== state.assignee) return false;
      if(state.supportType && c.supportType !== state.supportType) return false;
      if(state.recipient && c.recipientType !== state.recipient) return false;
      if(state.ptype && c.productSelectionType !== state.ptype) return false;
      if(state.spare && c.spareRequired !== state.spare) return false;
      if(state.from && ymd(c.ticketRaiseDate) < state.from) return false;
      if(state.to && ymd(c.ticketRaiseDate) > state.to) return false;
      if(q.length){
        const p = productOf(c);
        const hay = [c.ticketId, c.customerName, c.customerSegment, p.name, p.code, p.group, p.oem, c.issueReported,
          c.detailsIssueFound, c.correctiveAction, c.assignedEmpId, c.assignedEmpName, c.givenToName, c.givenToId,
          c.supportEngineerName, c.spareName, c.callStatus].join(' ').toLowerCase();
        if(!q.every(w => hay.indexOf(w) >= 0)) return false;
      }
      return true;
    });
    const chips = $('#chips', page);
    const active = Object.keys(state).filter(k => state[k] && k !== 'q');
    chips.classList.toggle('hide', !active.length);
    chips.innerHTML = active.map(k => '<span class="chip">' + esc(k) + ': ' + esc(state[k]) + '<button data-k="' + k + '">&times;</button></span>').join('');
    $$('button', chips).forEach(b => b.onclick = () => { state[b.dataset.k] = ''; syncInputs(); apply(); });
    table.redraw(rows);
    current = rows;
  }
  function syncInputs(){
    $('#fst').value = state.status; $('#fsg').value = state.segment; $('#fgr').value = state.group;
    if($('#fas')) $('#fas').value = state.assignee;
    $('#fsp').value = state.supportType; $('#frc').value = state.recipient; $('#fpt').value = state.ptype;
    $('#fspa').value = state.spare; $('#ffr').value = state.from; $('#fto').value = state.to;
  }
  let current = [];
  const table = DataTable($('#tbl', page), {
    rows: [], sort:'ticketRaiseDate', dir:'desc',
    cols: [
      { key:'ticketId', label:'Ticket', nowrap:true, render:c => '<span class="tid">' + esc(c.ticketId) + '</span><span class="cellsub">' + fmtDT(c.ticketRaiseDate) + '</span>' },
      { key:'customerName', label:'Customer', render:c => esc(c.customerName) + '<span class="cellsub">' + esc(c.customerSegment) + '</span>' },
      { key:'itemName', label:'Product', sortVal:c => productOf(c).name, render:productLabel },
      { key:'issueReported', label:'Issue reported', render:c => '<div style="max-width:320px">' + esc(String(c.issueReported).slice(0, 110)) + (c.issueReported.length > 110 ? '…' : '') + '</div>' },
      { key:'assignedEmpName', label:'Assigned to', render:c => esc(c.assignedEmpName) + '<span class="cellsub">' + esc(c.assignedEmpId) + '</span>' },
      { key:'supportType', label:'Support given to', render:recipientLabel },
      { key:'callStatus', label:'Status', nowrap:true, render:c => statusBadge(c.callStatus) },
      { key:'act', label:'', sortable:false, nowrap:true, render:c => '<button class="btn sm" data-open="' + esc(c.ticketId) + '">Open</button>' }
    ],
    onRow: c => openCall(c.ticketId),
    emptyTitle:'No tickets match these filters', emptyText:'Clear a filter or widen the date range.'
  });
  apply();

  const bind = (id, key) => { const el = $('#' + id); if(el) el.onchange = () => { state[key] = el.value; apply(); }; };
  $('#fq').oninput = debounce(() => { state.q = $('#fq').value; apply(); }, 200);
  bind('fst','status'); bind('fsg','segment'); bind('fgr','group'); bind('fas','assignee');
  bind('fsp','supportType'); bind('frc','recipient'); bind('fpt','ptype'); bind('fspa','spare');
  bind('ffr','from'); bind('fto','to');
  $('#fclr').onclick = () => { state.openOnly = false; Object.keys(state).forEach(k => state[k] = ''); $('#fq').value = ''; syncInputs(); apply(); };
  $('#fexp').onclick = () => exportChooser(current, scope === 'mine' ? 'My_Calls' : 'Filtered');
  page.addEventListener('click', e => {
    const b = e.target.closest('[data-open]');
    if(b){ e.stopPropagation(); openCall(b.dataset.open); }
  });
}
VIEWS.calls = function(page, params){ if(!can('call.view.all')) return go('mycalls', params); callListView(page, params, 'all'); };
VIEWS.mycalls = function(page, params){ callListView(page, params, 'mine'); };

