    cols:[
      { key:'ticketId', label:'Ticket', nowrap:true, render:c => '<span class="tid">' + esc(c.ticketId) + '</span>' },
      { key:'ticketRaiseDate', label:'Raised', nowrap:true, render:c => fmtDate(c.ticketRaiseDate) +
        '<span class="cellsub">' + Math.floor((Date.now() - new Date(c.ticketRaiseDate)) / 86400000) + ' days ago</span>' },
      { key:'customerName', label:'Customer', render:c => esc(c.customerName) },
      { key:'itemName', label:'Product', sortVal:c => productOf(c).name, render:productLabel },
      { key:'assignedEmpName', label:'Assigned to', render:c => esc(c.assignedEmpName) + '<span class="cellsub">' + esc(c.assignedEmpId) + '</span>' },
      { key:'callStatus', label:'Status', nowrap:true, render:c => statusBadge(c.callStatus) },
      { key:'a', label:'', sortable:false, nowrap:true, render:c => (isHD() || c.assignedEmpId === Session.user.employeeId)
        ? '<button class="btn sm pri" data-upd="' + esc(c.ticketId) + '">Update</button>' : '<span class="mut sm">read only</span>' }
    ],
    onRow: c => openCall(c.ticketId),
