/* ============================================================
   9b. PHOTO CAPTURE — compressed in the browser, attached to the ticket
   ============================================================ */
function PhotoInput(mount, opts){
  opts = opts || {};
  const max = opts.max || CONFIG.photo.maxPerEntry;
  const wrap = document.createElement('div');
  wrap.className = 'phot';
  wrap.innerHTML =
    '<div class="phot-drop" id="phDrop">' +
      '<input type="file" accept="image/*" capture="environment" multiple hidden>' +
      '<div class="phot-cta"><b>Add photo</b><span class="mut sm">Camera or file · up to ' + max + ' images · resized and compressed before saving</span></div>' +
    '</div><div class="phot-grid" id="phGrid"></div>';
  mount.appendChild(wrap);
  const input = $('input', wrap), grid = $('#phGrid', wrap), drop = $('#phDrop', wrap);
  let items = [];

  function draw(){
    grid.innerHTML = items.map((it, i) =>
      '<figure class="phot-th"><img src="' + it.dataUrl + '" alt=""><button type="button" class="x" data-i="' + i + '" title="Remove">&times;</button>' +
      '<figcaption>' + esc(it.name.slice(0, 18)) + ' · ' + fmtBytes(it.bytes) + '</figcaption></figure>').join('');
    $$('button.x', grid).forEach(b => b.onclick = () => { items.splice(+b.dataset.i, 1); draw(); });
    drop.classList.toggle('full', items.length >= max);
  }
  let isTaking = false; 
  async function take(files){
    if(isTaking) return;
    isTaking = true;

    for(const f of Array.from(files)){
      // Strict Duplicate Check: Naam, Size aur Last Modified date se check karein
      const alreadyExists = items.some(existing => existing.name === f.name && existing.bytes === f.size);
      if(alreadyExists) continue; 

      if(items.length >= max){ 
        toast('Up to ' + max + ' photos per entry.', 'warn'); 
        break; 
      }
      
      try { 
        const compressed = await compressImage(f);
        // Ek aur security check taaki compressed data bhi duplicate na ho
        const compressedExists = items.some(existing => existing.bytes === compressed.bytes && existing.name === compressed.name);
        if(!compressedExists) {
          items.push(compressed);
        }
      }
      catch(e){ 
        toast(e.message, 'err'); 
      }
    }
    draw();
    isTaking = false; 
  }
  drop.onclick = () => { if(items.length < max) input.click(); };
  input.onchange = () => { take(input.files); input.value = ''; };
  drop.ondragover = e => { e.preventDefault(); drop.classList.add('over'); };
  drop.ondragleave = () => drop.classList.remove('over');
  drop.ondrop = e => { e.preventDefault(); drop.classList.remove('over'); take(e.dataTransfer.files); };
  return { items: () => items, clear(){ items = []; draw(); } };
}

/* Full-size viewer for photos already on a ticket */
function openPhoto(meta){
  const body = document.createElement('div');
  body.innerHTML = '<div class="phot-view"><img src="' + API.photoData(meta.id) + '" alt=""></div>' +
    '<div class="mut sm" style="margin-top:10px">' + esc(meta.name) + ' · ' + fmtBytes(meta.bytes) + ' · ' +
    (meta.stage === 'LOG' ? 'attached at call log' : 'attached at call update') + ' by ' + esc(meta.byName || meta.by) +
    ' on ' + fmtDT(meta.at) + '</div>';
  Modal.open({ title:'Photo — ' + meta.ticketId, size:'wide', body, buttons:[
    { label:'Download', onClick(){ const a = document.createElement('a'); a.href = API.photoData(meta.id); a.download = meta.ticketId + '_' + meta.name; a.click(); } },
    { label:'Close', cls:'pri' }] });
}
function photoStrip(c, canEdit, onChange){
  const list = (c.photos || []);
  if(!list.length) return '<div class="mut sm">No photos attached.</div>';
  return '<div class="phot-grid">' + list.map(p =>
    '<figure class="phot-th" data-p="' + p.id + '"><img src="' + API.photoData(p.id) + '" alt="">' +
    (canEdit ? '<button type="button" class="x" data-del="' + p.id + '" title="Remove">&times;</button>' : '') +
    '<figcaption>' + (p.stage === 'LOG' ? 'Call log' : 'Update') + ' · ' + fmtDate(p.at) + '</figcaption></figure>').join('') + '</div>';
}

/* ============================================================
   10. PRODUCT PICKER — cascading master selection + other product
   ============================================================ */
function ProductPicker(mount){
  const cfg = Store.db.config;
  const wrap = document.createElement('div');
  wrap.innerHTML =
    '<div class="fld"><label>Product selection type<span class="req">*</span></label>' +
    '<div class="seg" id="ppSeg"><button type="button" data-v="MASTER" class="on">Master product</button><button type="button" data-v="OTHER">Other product</button></div>' +
    '<div class="hint">Choose “Other product” when the item is not in the asset master. The call is still logged; the item is stored against the ticket only.</div></div>' +
    '<div id="ppMaster">' +
      '<div class="frow f2">' +
        '<div class="fld"><label><span class="stepn">1</span> OEM</label><select class="inp" id="ppOem"><option value="">All OEMs</option></select></div>' +
        '<div class="fld"><label><span class="stepn">2</span> Item group</label><select class="inp" id="ppGroup"><option value="">All groups</option></select></div>' +
      '</div>' +
      '<div class="fld"><label><span class="stepn">3</span> Item code<span class="req">*</span></label><div id="ppCode"></div>' +
        '<div class="hint">OEM and item group only narrow the list — the item code is what is saved, and it fills the rest in automatically.</div></div>' +
      '<div class="fld"><label>Item name</label><input class="inp" id="ppName" readonly placeholder="Select an item code"></div>' +
    '</div>' +
    '<div id="ppOther" class="hide"><fieldset class="box"><legend>Other product details</legend>' +
      '<div class="frow">' +
        '<div class="fld"><label>Item name<span class="req">*</span></label><input class="inp" id="opName" maxlength="120"></div>' +
        '<div class="fld"><label>Item group</label><input class="inp" id="opGroup" maxlength="60" placeholder="e.g. UPS System"></div>' +
        '<div class="fld"><label>OEM</label><input class="inp" id="opOem" maxlength="60"></div>' +
        '<div class="fld"><label>Item code / reference</label><input class="inp" id="opCode" maxlength="40"></div>' +
      '</div>' +
      '<div class="fld"><label>Description<span class="req">*</span></label><textarea class="inp" id="opDesc" maxlength="500" placeholder="Rating, serial number, where it is installed, anything that identifies the unit"></textarea></div>' +
      '<div class="note warn">This item is recorded against the ticket only. It is not added to the asset master — it shows up in the “Other products used” report so the master can be corrected later.</div>' +
    '</fieldset></div>' +
    '<div class="fld"><label>Product phase<span class="req">*</span></label><select class="inp" id="ppPhase">' +
      '<option value="">Select…</option>' + cfg.productPhases.map(p => '<option>' + esc(p) + '</option>').join('') + '</select>' +
      '<div class="hint">Input : output phase configuration of the unit.</div></div>';
  mount.appendChild(wrap);

  let type = 'MASTER', chosen = null;
  const gSel = $('#ppGroup', wrap), oSel = $('#ppOem', wrap), nInp = $('#ppName', wrap);
  const live = () => Store.db.assets.filter(a => a.active);
  const oems = Array.from(new Set(live().map(a => a.oem || ''))).filter(Boolean).sort();
  oSel.innerHTML = '<option value="">All OEMs</option>' + oems.map(o => '<option>' + esc(o) + '</option>').join('') +
    '<option value="__NONE__">OEM not recorded in master</option>';

  /* OEM is blank on most asset rows, so group is filtered by OEM, never hidden by it */
  function refreshGroups(){
    const o = oSel.value;
    const list = live().filter(a => !o ? true : (o === '__NONE__' ? !a.oem : a.oem === o));
    const gs = Array.from(new Set(list.map(a => a.itemGroup))).sort();
    const keep = gSel.value;
    gSel.innerHTML = '<option value="">All groups</option>' + gs.map(g => '<option>' + esc(g) + '</option>').join('');
    if(gs.indexOf(keep) >= 0) gSel.value = keep;
  }
  refreshGroups();
  const cb = Combobox($('#ppCode', wrap), {
    placeholder:'Type item code or item name…',
    source(q){
      const f = { itemGroup: gSel.value || '', oem: oSel.value === '__NONE__' ? '' : (oSel.value || '') };
      let list = API.searchAssets(q, { itemGroup:f.itemGroup, oem: oSel.value ? f.oem : undefined }, 60);
      if(oSel.value === '__NONE__') list = list.filter(a => !a.oem);
      return list.map(a => ({ label:a.itemCode + ' — ' + a.itemName, sub:a.itemGroup + (a.oem ? ' · ' + a.oem : ' · OEM not recorded'), a }));
    },
    onSelect(it){
      chosen = it ? it.a : null;
      nInp.value = chosen ? chosen.itemName : '';
      if(chosen){
        oSel.value = chosen.oem || '__NONE__';
        refreshGroups();
        gSel.value = chosen.itemGroup;
      }
    }
  });
  gSel.onchange = () => { cb.clear(); chosen = null; nInp.value = ''; };
  oSel.onchange = () => { refreshGroups(); cb.clear(); chosen = null; nInp.value = ''; };
  $$('#ppSeg button', wrap).forEach(b => b.onclick = () => {
    $$('#ppSeg button', wrap).forEach(x => x.classList.remove('on'));
    b.classList.add('on'); type = b.dataset.v;
    $('#ppMaster', wrap).classList.toggle('hide', type !== 'MASTER');
    $('#ppOther', wrap).classList.toggle('hide', type !== 'OTHER');
  });

  return {
    validate(){
      const errs = [];
      if(type === 'MASTER'){
        if(!chosen){ errs.push('Select an item code from the asset master, or switch to “Other product”.'); cb.invalid(true); }
        else cb.invalid(false);
      }
      const ph = $('#ppPhase', wrap);
      ph.classList.toggle('err', !ph.value);
      if(!ph.value) errs.push('Product phase is required.');
      if(type === 'OTHER'){
        const n = $('#opName', wrap), d = $('#opDesc', wrap);
        n.classList.toggle('err', !n.value.trim()); d.classList.toggle('err', !d.value.trim());
        if(!n.value.trim()) errs.push('Other product needs an item name.');
        if(!d.value.trim()) errs.push('Other product needs a description.');
      }
      return errs;
    },
    value(){
      const phase = $('#ppPhase', wrap).value;
      if(type === 'MASTER') return { productSelectionType:'MASTER', itemGroup:chosen.itemGroup, oem:chosen.oem, itemName:chosen.itemName, itemCode:chosen.itemCode, productPhase:phase, otherProduct:null };
      return { productSelectionType:'OTHER', itemGroup:'', oem:'', itemName:'', itemCode:'', productPhase:phase,
        otherProduct: { itemGroup:$('#opGroup', wrap).value.trim(), oem:$('#opOem', wrap).value.trim(),
          itemName:$('#opName', wrap).value.trim(), itemCode:$('#opCode', wrap).value.trim(), description:$('#opDesc', wrap).value.trim() } };
    }
  };
}

