VIEWS.supporttaken = function(page){
  const calls = API.calls(c => c.supportType === 'Remote Support' && c.recipientType);
  const rows = calls.map(c => {
    const m = c.recipientType === 'MASTER_USER' ? Store.db.supportTakenUsers.find(u => u.employeeId === c.givenToId) : null;
    const o = c.otherRecipient || {};
    return {
      empId: c.recipientType === 'DIRECT_CUSTOMER' ? '—' : (c.givenToId || '—'),
      name: c.recipientType === 'DIRECT_CUSTOMER' ? 'Direct Customer' : (c.givenToName || '—'),
      type: c.recipientType,
      jobTitle: m ? m.jobTitle : (o.jobTitle || ''), department: m ? m.department : (o.department || ''),
      sub: m ? m.subDepartment : (o.subDepartment || ''), branch: m ? m.branch : (o.branch || ''),
      location: m ? m.location : (o.location || c.customerName), call: c
    };
  });
  const byType = t => rows.filter(r => r.type === t).length;
  page.innerHTML =
    '<div class="kpis">' +
      '<div class="kpi" style="--k:var(--ok)"><div class="lbl">To master users</div><div class="val num">' + byType('MASTER_USER') + '</div><div class="sub">from the support taken master</div></div>' +
      '<div class="kpi" style="--k:var(--signal)"><div class="lbl">Direct customer</div><div class="val num">' + byType('DIRECT_CUSTOMER') + '</div><div class="sub">no employee record involved</div></div>' +
      '<div class="kpi" style="--k:#7A4FD6"><div class="lbl">Other / manual</div><div class="val num">' + byType('OTHER_USER') + '</div><div class="sub">captured on the ticket</div></div>' +
      '<div class="kpi" style="--k:var(--primary)"><div class="lbl">Distinct recipients</div><div class="val num">' + new Set(rows.map(r => r.name)).size + '</div><div class="sub">people helped</div></div>' +
    '</div>' +
    '<div class="grid2" style="margin-bottom:16px">' +
      '<div class="card"><div class="card-h"><h3>Most supported people</h3></div><div class="card-b">' +
        hbars(topCount(rows.filter(r => r.type === 'MASTER_USER'), r => r.name, 8)) + '</div></div>' +
      '<div class="card"><div class="card-h"><h3>Support by sub department</h3></div><div class="card-b">' +
        hbars(topCount(rows.filter(r => r.sub), r => r.sub, 6)) + '</div></div>' +
    '</div>' +
    '<div class="card"><div class="toolbar"><div class="f grow"><label>Search recipients</label>' +
      '<input class="inp" id="stq" placeholder="Employee ID, name, job title, department, branch, location…"></div>' +
      '<div class="f"><label>Recipient type</label><select class="inp" id="stt"><option value="">All</option>' +
      '<option value="MASTER_USER">Master user</option><option value="DIRECT_CUSTOMER">Direct customer</option><option value="OTHER_USER">Other user</option></select></div>' +
      '<div class="f" style="min-width:auto"><label>&nbsp;</label><button class="btn" id="stx">Export report</button></div></div><div id="stTbl"></div></div>';

  let view = rows;
  const t = DataTable($('#stTbl', page), {
    rows,
    cols:[
      { key:'empId', label:'Employee ID', nowrap:true, render:r => esc(r.empId) },
      { key:'name', label:'Name', render:r => esc(r.name) + (r.type !== 'MASTER_USER' ? '<span class="cellsub">' + (r.type === 'DIRECT_CUSTOMER' ? 'direct customer' : 'other user') + '</span>' : '') },
      { key:'jobTitle', label:'Job title', render:r => esc(r.jobTitle || '—') },
      { key:'sub', label:'Sub department', render:r => esc(r.sub || '—') },
      { key:'location', label:'Location', render:r => esc(r.location || '—') },
      { key:'ticket', label:'Ticket', nowrap:true, sortVal:r => r.call.ticketId, render:r => '<span class="tid">' + esc(r.call.ticketId) + '</span><span class="cellsub">' + fmtDate(r.call.ticketRaiseDate) + '</span>' },
      { key:'customer', label:'Customer', sortVal:r => r.call.customerName, render:r => esc(r.call.customerName) },
      { key:'owner', label:'Given by', sortVal:r => r.call.assignedEmpName, render:r => esc(r.call.assignedEmpName) + '<span class="cellsub">' + esc(r.call.assignedEmpId) + '</span>' },
      { key:'status', label:'Status', nowrap:true, sortVal:r => r.call.callStatus, render:r => statusBadge(r.call.callStatus) }
    ],
    onRow: r => openCall(r.call.ticketId),
    emptyTitle:'No remote support recorded yet', emptyText:'Recipients appear here once a ticket is updated with support type “Remote Support”.'
  });
  function refilter(){
    const q = $('#stq').value.toLowerCase().split(/\s+/).filter(Boolean), ty = $('#stt').value;
    view = rows.filter(r => {
      if(ty && r.type !== ty) return false;
      const hay = [r.empId, r.name, r.jobTitle, r.department, r.sub, r.branch, r.location, r.call.ticketId, r.call.customerName].join(' ').toLowerCase();
      return q.every(w => hay.indexOf(w) >= 0);
    });
    t.redraw(view);
  }
  $('#stq').oninput = debounce(refilter, 200);
  $('#stt').onchange = refilter;
  $('#stx').onclick = () => exportGeneric('Support_Taken_Report',
    ['Employee ID','Name','Recipient Type','Job Title','Department','Sub Department','Branch','Location','Ticket ID','Customer','Product','Assigned Support User','Support Type','Issue','Corrective Action','Status','Date'],
    view.map(r => [r.empId, r.name, r.type, r.jobTitle, r.department, r.sub, r.branch, r.location, r.call.ticketId, r.call.customerName,
      productOf(r.call).name, r.call.assignedEmpId + ' – ' + r.call.assignedEmpName, r.call.supportType, r.call.issueReported,
      r.call.correctiveAction, r.call.callStatus, fmtDate(r.call.ticketRaiseDate)]));
};
function topCount(arr, keyFn, n){
  const m = {};
  arr.forEach(x => { const k = keyFn(x) || '—'; m[k] = (m[k] || 0) + 1; });
  return Object.keys(m).map(k => ({ k, v:m[k] })).sort((a, b) => b.v - a.v).slice(0, n || 8);
}

/* ============================================================
   16. REPORTS
   ============================================================ */
VIEWS.reports = function(page){
  const calls = API.calls();
  page.innerHTML = '<div class="card"><div class="tabs" id="rtabs">' +
    '<button class="on" data-r="summary">Call summary</button>' +
    '<button data-r="user">By support user</button>' +
    '<button data-r="product">By product</button>' +
    '<button data-r="customer">By customer</button>' +
    (isHD() ? '<button data-r="other">Other products used</button>' : '') +
    '<button data-r="ageing">Ageing</button></div><div class="card-b" id="rbody"></div></div>';
  const rb = $('#rbody', page);

  const R = {
    summary(){
      const st = Store.db.config.callStatuses.map(s => [s, calls.filter(c => c.callStatus === s).length]);
      const months = [];
      for(let i = 5; i >= 0; i--){
        const d = new Date(new Date().getFullYear(), new Date().getMonth() - i, 1), k = ym(d);
        const set = calls.filter(c => ym(c.ticketRaiseDate) === k);
        months.push([MONTHS[d.getMonth()] + ' ' + d.getFullYear(), set.length,
          set.filter(c => ['Closed','Resolved'].indexOf(c.callStatus) >= 0).length,
          set.filter(c => c.supportType === 'Remote Support').length,
          set.filter(c => c.supportType === 'Own Visit with Support Engineer').length]);
      }
      rb.innerHTML = '<div class="sec-title"><h3>Status split</h3><span class="spacer"></span>' +
        '<button class="btn sm" id="rx1">Export</button></div>' +
        tbl(['Status','Tickets','Share'], st.filter(r => r[1]).map(r => [r[0], r[1], pct(r[1], calls.length)])) +
        '<div class="sec-title" style="margin-top:22px"><h3>Last six months</h3></div>' +
        tbl(['Month','Logged','Closed / resolved','Remote support','Own visit'], months);
      $('#rx1').onclick = () => exportGeneric('Call_Status_Summary', ['Status','Tickets','Share'], st.map(r => [r[0], r[1], pct(r[1], calls.length)]));
    },
    user(){
      const users = API.activeUsers();
      const rows = users.map(u => {
        const mine = calls.filter(c => c.assignedEmpId === u.employeeId);
        return [u.employeeId, u.fullName, u.location, mine.length,
          mine.filter(c => OPEN_STATUSES.indexOf(c.callStatus) >= 0).length,
          mine.filter(c => c.callStatus === 'Closed').length,
          mine.filter(c => c.supportType === 'Remote Support').length,
          mine.filter(c => c.supportType === 'Own Visit with Support Engineer').length];
      }).sort((a, b) => b[3] - a[3]);
      rb.innerHTML = '<div class="sec-title"><h3>Workload by remote support user</h3><span class="spacer"></span><button class="btn sm" id="rx2">Export</button></div>' +
        tbl(['Emp ID','Name','Location','Total','Open','Closed','Remote','Own visit'], rows);
      $('#rx2').onclick = () => exportGeneric('Calls_By_Support_User', ['Emp ID','Name','Location','Total','Open','Closed','Remote','Own Visit'], rows);
    },
    product(){
      const m = {};
      calls.forEach(c => { const p = productOf(c); const k = (p.group || '—') + '||' + (p.oem || '—') + '||' + (p.name || '—');
        m[k] = m[k] || { g:p.group, o:p.oem, n:p.name, code:p.code, v:0, open:0 };
        m[k].v++; if(OPEN_STATUSES.indexOf(c.callStatus) >= 0) m[k].open++; });
      const rows = Object.values(m).sort((a, b) => b.v - a.v).map(x => [x.g || '—', x.o || '—', x.n, x.code || '—', x.v, x.open]);
      rb.innerHTML = '<div class="sec-title"><h3>Calls by product</h3><span class="spacer"></span><button class="btn sm" id="rx3">Export</button></div>' +
        tbl(['Item group','OEM','Item name','Item code','Tickets','Open'], rows.slice(0, 60));
      $('#rx3').onclick = () => exportGeneric('Calls_By_Product', ['Item Group','OEM','Item Name','Item Code','Tickets','Open'], rows);
    },
    customer(){
      const m = {};
      calls.forEach(c => { m[c.customerName] = m[c.customerName] || { seg:c.customerSegment, v:0, open:0, remote:0 };
        m[c.customerName].v++; if(OPEN_STATUSES.indexOf(c.callStatus) >= 0) m[c.customerName].open++;
        if(c.supportType === 'Remote Support') m[c.customerName].remote++; });
      const rows = Object.keys(m).map(k => [k, m[k].seg, m[k].v, m[k].open, m[k].remote]).sort((a, b) => b[2] - a[2]);
      rb.innerHTML = '<div class="sec-title"><h3>Calls by customer</h3><span class="spacer"></span><button class="btn sm" id="rx4">Export</button></div>' +
        tbl(['Customer','Segment','Tickets','Open','Remote support'], rows);
      $('#rx4').onclick = () => exportGeneric('Calls_By_Customer', ['Customer','Segment','Tickets','Open','Remote Support'], rows);
    },
    other(){
      const others = calls.filter(c => c.productSelectionType === 'OTHER' && c.otherProduct);
      const grouped = {};
      others.forEach(c => { const k = (c.otherProduct.itemName || '').toLowerCase();
        grouped[k] = grouped[k] || { rows:[], n:0 }; grouped[k].rows.push(c); grouped[k].n++; });
      const rows = others.map(c => [c.ticketId, fmtDate(c.ticketRaiseDate), c.otherProduct.itemName, c.otherProduct.itemGroup || '—',
        c.otherProduct.oem || '—', c.otherProduct.itemCode || '—', c.otherProduct.description, c.createdBy,
        grouped[(c.otherProduct.itemName || '').toLowerCase()].n]);
      rb.innerHTML = '<div class="note info" style="margin-bottom:14px">These items were entered manually because they were missing from the asset master. ' +
        'Anything appearing repeatedly is a candidate to add to <b>Assets Data</b>.</div>' +
        '<div class="sec-title"><h3>Other products used</h3><span class="spacer"></span><button class="btn sm" id="rx5">Export</button></div>' +
        tbl(['Ticket ID','Date','Product name','Item group','OEM','Item code','Description','Entered by','Times used'], rows);
      const x = $('#rx5'); if(x) x.onclick = () => exportGeneric('Other_Products_Used',
        ['Ticket ID','Date','Product Name','Item Group','OEM','Item Code','Description','Entered By','Number of Uses'], rows);
    },
    ageing(){
      const open = calls.filter(c => OPEN_STATUSES.indexOf(c.callStatus) >= 0);
      const bucket = d => d <= 2 ? '0–2 days' : d <= 7 ? '3–7 days' : d <= 15 ? '8–15 days' : d <= 30 ? '16–30 days' : 'over 30 days';
      const m = {};
      open.forEach(c => { const d = Math.floor((Date.now() - new Date(c.ticketRaiseDate)) / 86400000); const b = bucket(d); m[b] = (m[b] || 0) + 1; });
      const order = ['0–2 days','3–7 days','8–15 days','16–30 days','over 30 days'];
      const rows = open.map(c => [c.ticketId, fmtDate(c.ticketRaiseDate),
        Math.floor((Date.now() - new Date(c.ticketRaiseDate)) / 86400000), c.customerName, productOf(c).name, c.assignedEmpId, c.callStatus])
        .sort((a, b) => b[2] - a[2]);
      rb.innerHTML = '<div class="grid2" style="margin-bottom:18px"><div><div class="sec-title"><h3>Open tickets by age</h3></div>' +
        hbars(order.filter(o => m[o]).map(o => ({ k:o, v:m[o], c:o === 'over 30 days' ? 'var(--danger)' : (o === '16–30 days' ? 'var(--signal)' : 'var(--primary)') }))) + '</div>' +
        '<div><div class="sec-title"><h3>Oldest open tickets</h3></div>' +
        tbl(['Ticket','Raised','Days','Customer','Owner','Status'], rows.slice(0, 8).map(r => [r[0], r[1], r[2], r[3], r[5], r[6]])) + '</div></div>' +
        '<div class="sec-title"><h3>All open tickets</h3><span class="spacer"></span><button class="btn sm" id="rx6">Export</button></div>' +
        tbl(['Ticket','Raised','Days open','Customer','Product','Owner','Status'], rows.slice(0, 60));
      $('#rx6').onclick = () => exportGeneric('Open_Call_Ageing', ['Ticket','Raised','Days Open','Customer','Product','Owner','Status'], rows);
    }
  };
  function pct(a, b){ return b ? Math.round(a * 1000 / b) / 10 + '%' : '0%'; }
  function tbl(head, rows){
    return '<div class="tbl-wrap" style="border:1px solid var(--line);border-radius:var(--radius)"><table class="tbl"><thead><tr>' +
      head.map(h => '<th>' + esc(h) + '</th>').join('') + '</tr></thead><tbody>' +
      (rows.length ? rows.map(r => '<tr>' + r.map(c => '<td>' + esc(c) + '</td>').join('') + '</tr>').join('')
        : '<tr><td colspan="' + head.length + '"><div class="empty"><b>Nothing to report yet</b></div></td></tr>') + '</tbody></table></div>';
  }
  $$('#rtabs button', page).forEach(b => b.onclick = () => {
    $$('#rtabs button', page).forEach(x => x.classList.remove('on'));
    b.classList.add('on'); R[b.dataset.r]();
  });
  R.summary();
};

