/* ============================================================
   19. IMPORT WIZARD
   ============================================================ */
const IMPORT_SPECS = {
  assets: { title:'Asset master', file:'Assets Data', key:'itemCode',
    cols:{ 'Item Group':'itemGroup', 'OEM':'oem', 'Item Name':'itemName', 'Item Code':'itemCode' },
    required:['Item Group','Item Name','Item Code'] },
  users: { title:'Remote support user master', file:'User List', key:'employeeId',
    cols:{ 'Employee ID':'employeeId', 'Full Name':'fullName', 'Department':'department', 'Location':'location' },
    required:['Employee ID','Full Name'] },
  supportTaken: { title:'Support taken user master', file:'Remote Support Taken User List', key:'employeeId',
    cols:{ 'Employee ID':'employeeId', 'Full Name':'fullName', 'Date Of Joining':'dateOfJoining', 'Job Title':'jobTitle',
      'Department':'department', 'Sub Department':'subDepartment', 'Branch':'branch', 'Location':'location' },
    required:['Employee ID','Full Name'] }
};
function importWizard(kind){
  const spec = IMPORT_SPECS[kind];
  const body = document.createElement('div');
  body.innerHTML = '<div class="note info" style="margin-bottom:14px">Upload <b>' + esc(spec.file) + '</b> as .xlsx or .csv. ' +
    'The first row must contain the column headers exactly as supplied: <span class="mono">' + Object.keys(spec.cols).join(', ') + '</span>.</div>' +
    '<div class="drop" id="drop"><b>Drop the file here, or click to choose</b><small>.xlsx or .csv · nothing is written until you confirm</small>' +
    '<input type="file" id="fileIn" accept=".xlsx,.csv" class="hide"></div><div id="impResult"></div>';
  const h = Modal.open({ title:'Import ' + spec.title, size:'wide', body, buttons:[{ label:'Close' }] });
  const drop = $('#drop', body), input = $('#fileIn', body);
  drop.onclick = () => input.click();
  drop.ondragover = e => { e.preventDefault(); drop.classList.add('over'); };
  drop.ondragleave = () => drop.classList.remove('over');
  drop.ondrop = e => { e.preventDefault(); drop.classList.remove('over'); if(e.dataTransfer.files[0]) handle(e.dataTransfer.files[0]); };
  input.onchange = () => { if(input.files[0]) handle(input.files[0]); };

  async function handle(file){
    $('#impResult', body).innerHTML = '<div class="note info">Reading ' + esc(file.name) + '…</div>';
    let rows;
    try {
      rows = /\.csv$/i.test(file.name) ? csvParse(await file.text()) : await readXlsx(file);
    } catch(e){ $('#impResult', body).innerHTML = '<div class="note warn">' + esc(e.message) + '</div>'; return; }
    if(!rows || rows.length < 2){ $('#impResult', body).innerHTML = '<div class="note warn">The file has no data rows.</div>'; return; }
    const header = rows[0].map(x => String(x).trim());
    const missing = spec.required.filter(c => header.indexOf(c) < 0);
    if(missing.length){
      $('#impResult', body).innerHTML = '<div class="note warn"><b>Column check failed</b><br>Missing: ' + esc(missing.join(', ')) +
        '<br>Found: <span class="mono">' + esc(header.join(', ')) + '</span></div>';
      return;
    }
    const idx = {}; Object.keys(spec.cols).forEach(c => idx[c] = header.indexOf(c));
    const seen = {}, valid = [], invalid = [], updates = [], creates = [], unchanged = [];
    rows.slice(1).forEach((r, i) => {
      const rec = {};
      Object.keys(spec.cols).forEach(c => { const j = idx[c]; rec[spec.cols[c]] = j >= 0 ? cleanCell(r[j]) : ''; });
      if(rec.dateOfJoining) rec.dateOfJoining = excelDate(rec.dateOfJoining);
      const keyVal = (rec[spec.key] || '').toUpperCase();
      const problems = [];
      spec.required.forEach(c => { if(!rec[spec.cols[c]]) problems.push(c + ' is blank'); });
      if(keyVal && seen[keyVal]) problems.push('duplicate ' + spec.key + ' inside the file (row ' + seen[keyVal] + ')');
      if(problems.length){ invalid.push({ row:i + 2, rec, why:problems.join('; ') }); return; }
      seen[keyVal] = i + 2;
      const existing = kind === 'assets'
        ? Store.db.assets.find(a => a.itemCode.toUpperCase() === keyVal)
        : (kind === 'users' ? Store.db.users.find(u => u.employeeId.toUpperCase() === keyVal)
                            : Store.db.supportTakenUsers.find(u => u.employeeId.toUpperCase() === keyVal));
      if(!existing) creates.push(rec);
      else {
        const changed = Object.values(spec.cols).some(f => (existing[f] || '') !== (rec[f] || ''));
        (changed ? updates : unchanged).push(rec);
      }
      valid.push(rec);
    });
    const box = $('#impResult', body);
    box.innerHTML = '<div class="imp-sum">' +
      '<div><b class="num">' + (rows.length - 1) + '</b><small>rows read</small></div>' +
      '<div><b class="num" style="color:var(--ok)">' + creates.length + '</b><small>new records</small></div>' +
      '<div><b class="num" style="color:var(--primary)">' + updates.length + '</b><small>will be updated</small></div>' +
      '<div><b class="num" style="color:var(--muted)">' + unchanged.length + '</b><small>unchanged</small></div>' +
      '<div><b class="num" style="color:var(--danger)">' + invalid.length + '</b><small>invalid</small></div></div>' +
      (invalid.length ? '<div class="note warn" style="margin-bottom:12px"><b>Skipped rows</b><ul style="margin:6px 0 0;padding-left:18px">' +
        invalid.slice(0, 8).map(x => '<li>Row ' + x.row + ' — ' + esc(x.why) + '</li>').join('') +
        (invalid.length > 8 ? '<li>…and ' + (invalid.length - 8) + ' more</li>' : '') + '</ul></div>' : '') +
      '<div class="sec-title"><h3>Preview</h3><span class="spacer"></span><span class="mut sm">first 10 valid rows</span></div>' +
      '<div class="tbl-wrap" style="border:1px solid var(--line);border-radius:var(--radius)"><table class="tbl"><thead><tr>' +
      Object.keys(spec.cols).map(c => '<th>' + esc(c) + '</th>').join('') + '</tr></thead><tbody>' +
      valid.slice(0, 10).map(r => '<tr>' + Object.values(spec.cols).map(f => '<td>' + esc(r[f]) + '</td>').join('') + '</tr>').join('') +
      '</tbody></table></div>' +
      '<div class="btn-row" style="margin-top:14px"><button class="btn pri" id="impGo">Import ' + (creates.length + updates.length) + ' record(s)</button></div>';
    $('#impGo', body).onclick = () => {
      try {
        const res = API.importRows(kind, creates.concat(updates));
        h.close();
        toast(res.created + ' added, ' + res.updated + ' updated.', 'ok');
        go(currentView);
      } catch(e){ toast(e.message, 'err'); }
    };
  }
}

