function userForm(u){
  const isNew = !u;
  u = u || { employeeId:'', fullName:'', department:'Operation', location:'', branch:'', zone:'', designation:'', sourceRole:'', roleOverride:'', role:'TRCE', active:true };
  const body = document.createElement('div');
  body.innerHTML = '<div class="frow">' +
    '<div class="fld"><label>Employee ID<span class="req">*</span></label><input class="inp" id="ufId" value="' + esc(u.employeeId) + '"' + (isNew ? '' : ' readonly') + ' maxlength="20"></div>' +
    '<div class="fld"><label>Full name<span class="req">*</span></label><input class="inp" id="ufName" value="' + esc(u.fullName) + '" maxlength="80"></div>' +
    '<div class="fld"><label>Department</label><input class="inp" id="ufDept" value="' + esc(u.department) + '" maxlength="60"></div>' +
    '<div class="fld"><label>Location</label><input class="inp" id="ufLoc" value="' + esc(u.location) + '" maxlength="60"></div>' +
    '<div class="fld"><label>Branch</label><input class="inp" id="ufBranch" value="' + esc(u.branch || '') + '" maxlength="40"></div>' +
    '<div class="fld"><label>Zone</label><input class="inp" id="ufZone" value="' + esc(u.zone || '') + '" maxlength="40"></div>' +
    '<div class="fld"><label>Designation</label><input class="inp" id="ufDesig" value="' + esc(u.designation || '') + '" maxlength="60"></div>' +
    '<div class="fld"><label>Application role<span class="req">*</span></label><select class="inp" id="ufRole">' +
      Object.keys(ROLES).map(r => '<option value="' + r + '"' + (r === u.role ? ' selected' : '') + '>' + esc(ROLES[r].label) + '</option>').join('') + '</select>' +
      '<div class="hint">The user list gives “' + esc(u.sourceRole || '—') + '”, which maps to <b>' + esc((ROLES[Store.db.config.roleMap[u.sourceRole]] || {}).label || 'TRCE User') + '</b>. Changing it here pins the role and survives the next sync.</div></div>' +
    '</div><div class="fld"><label class="chk"><input type="checkbox" id="ufAct"' + (u.active ? ' checked' : '') + '> Active — can sign in and receive calls</label></div>' +
    (isNew ? '<div class="note info">The new login starts with the default password <b>' + DEFAULT_PW + '</b> and is asked to change it at first sign-in.</div>'
           : '<div class="note info">Tickets already assigned to this user stay with them even if the login is deactivated.</div>');
  const h = Modal.open({ title: isNew ? 'Add login' : 'Edit ' + u.employeeId, body, buttons:[
    { label:'Cancel' },
    { label:'Save', cls:'pri', onClick(){
        const chosen = $('#ufRole', body).value;
        try { API.saveUser({ id:u.id, employeeId:$('#ufId', body).value, fullName:$('#ufName', body).value.trim(),
          department:$('#ufDept', body).value.trim(), location:$('#ufLoc', body).value.trim(),
          branch:$('#ufBranch', body).value.trim(), zone:$('#ufZone', body).value.trim(),
          designation:$('#ufDesig', body).value.trim(), sourceRole:u.sourceRole || '',
          managerCode:u.managerCode || '', managerName:u.managerName || '', pwSource:u.pwSource || 'LOCAL',
          roleOverride: chosen !== (Store.db.config.roleMap[u.sourceRole] || 'TRCE') ? chosen : '',
          role:chosen, active:$('#ufAct', body).checked,
          salt:u.salt, passwordHash:u.passwordHash, mustChange:u.mustChange, createdAt:u.createdAt }, isNew);
          h.close(); toast('Login saved.', 'ok'); go(currentView);
        } catch(e){ toast(e.message, 'err'); }
      } }
  ]});
}


/* ============================================================
   20b. LOGIN MASTER SYNC — SharePoint / GitHub hosted user file
   ============================================================ */
function openUserSync(){
  const cfg = Store.db.config.userSource, st = Store.db.userSync || {};
  const body = document.createElement('div');
  body.innerHTML =
    '<div class="note info">IDs, passwords and roles are read from the user file — never from the code. Point this at the ' +
      'SharePoint copy of <b>USER_LIST.xlsx</b> (or a <span class="mono">users.json</span> next to this page on GitHub) and every ' +
      'joiner, leaver or role change is picked up on the next sync. If the workbook has tabs named <b>ADMIN</b>, <b>HELPDESK Team</b> ' +
      'or <b>TRCE USER</b>, those tabs set who holds each role.</div>' +
    '<div class="fld"><label>User file URL</label><input class="inp" id="usUrl" value="' + esc(cfg.url || '') + '" placeholder="users.json  or  https://tenant.sharepoint.com/.../USER_LIST.xlsx?download=1"></div>' +
    '<div class="frow c2">' +
      '<div class="fld"><label>When to sync</label><select class="inp" id="usMode">' +
        ['auto|On every start','manual|Only when I click sync','off|Never — use the copy built into this file']
          .map(o => { const [v2, l] = o.split('|'); return '<option value="' + v2 + '"' + (cfg.mode === v2 ? ' selected' : '') + '>' + l + '</option>'; }).join('') +
      '</select></div>' +
      '<div class="fld"><label>Last sync</label><input class="inp" value="' + esc(st.lastSyncAt ? fmtDT(st.lastSyncAt) + ' · ' + st.count + ' rows' : 'Embedded copy only') + '" readonly></div>' +
    '</div>' +
    '<div class="fld"><label class="chk"><input type="checkbox" id="usDeact"> Deactivate logins that are no longer in the file (leavers)</label></div>' +
    '<div class="fld"><label class="chk"><input type="checkbox" id="usForce"> Overwrite passwords that users changed inside the app</label></div>' +
    '<div class="btn-row"><button class="btn pri" id="usFetch">Sync from URL</button>' +
      '<button class="btn" id="usHash">Build users.json without passwords</button></div>' +
    '<div class="note warn" style="margin-top:10px"><b>Before you publish on GitHub:</b> a file with a Password column exposes every ' +
      'login to anyone who can read the repository. Use a private repository or the SharePoint copy, or press ' +
      '<b>Build users.json without passwords</b> — it writes the same file with PasswordHash and PasswordSalt instead of the password itself.</div>' +
    '<div id="usOut" style="margin-top:12px"></div>';
  const h = Modal.open({ title:'Sync logins from the user list', size:'wide', body, buttons:[{ label:'Close', cls:'pri' }] });
  const out = $('#usOut', body);
  const opts = () => ({ deactivateMissing:$('#usDeact', body).checked, forcePassword:$('#usForce', body).checked });
  const report = r => {
    out.innerHTML = '<div class="note ok"><b>Sync complete</b><br>' + r.read + ' rows read · ' + r.created + ' new login' + (r.created === 1 ? '' : 's') +
      ' · ' + r.updated + ' updated · ' + r.pwChanged + ' password' + (r.pwChanged === 1 ? '' : 's') + ' refreshed · ' + r.deactivated + ' deactivated.' +
      (r.roleNote ? '<br>' + esc(r.roleNote) : '') + '</div>';
    buildNav();
  };
  $('#usFetch', body).onclick = async () => {
    const url = $('#usUrl', body).value.trim();
    out.innerHTML = '<div class="note info">Fetching…</div>';
    try {
      API.saveConfig({ userSource: Object.assign({}, cfg, { url, mode:$('#usMode', body).value }) });
      report(await API.ingestUserFile(url, url, opts()));
    } catch(e){
      out.innerHTML = '<div class="note warn"><b>Could not read the user file</b><br>' + esc(e.message) +
        '<br><span class="sm">Check that users.json sits in the same GitHub / SharePoint folder as this page. ' +
        'For SharePoint, the link must end in <span class="mono">?download=1</span> and the page must be served from the same tenant.</span></div>';
    }
  };
  $('#usHash', body).onclick = () => {
    const file = {
      version: 1, generatedOn: ymd(new Date().toISOString()),
      note: 'Passwords are stored as PasswordHash + PasswordSalt. The app verifies against these; the plain password is never in this file.',
      users: Store.db.users.map(u => ({
        EmpCode:u.employeeId, FullName:u.fullName, PasswordHash:u.passwordHash, PasswordSalt:u.salt,
        Branch:u.branch, Zone:u.zone, Designation:u.designation,
        ManagerCode:u.managerCode, ManagerName:u.managerName, Role:u.sourceRole || 'engineer'
      }))
    };
    download('users.json', new Blob([JSON.stringify(file, null, 1)], { type:'application/json' }));
    out.innerHTML = '<div class="note ok">users.json written with hashes only — safe to commit. Replace the copy on GitHub or SharePoint with this file.</div>';
  };
}

/* ============================================================
   21. AUDIT LOG
   ============================================================ */
VIEWS.audit = function(page){
  const acts = Array.from(new Set(Store.db.audit.map(a => a.action))).sort();
  page.innerHTML = '<div class="card"><div class="toolbar">' +
    '<div class="f grow"><label>Search</label><input class="inp" id="aq" placeholder="User, ticket, action, remark…"></div>' +
    '<div class="f"><label>Action</label><select class="inp" id="aa"><option value="">All</option>' + acts.map(a => '<option>' + esc(a) + '</option>').join('') + '</select></div>' +
    '<div class="f"><label>From</label><input type="date" class="inp" id="af"></div>' +
    '<div class="f"><label>To</label><input type="date" class="inp" id="at"></div>' +
    '<div class="f" style="min-width:auto"><label>&nbsp;</label><button class="btn" id="ax">Export</button></div></div><div id="aTbl"></div></div>';
  let view = Store.db.audit;
  const t = DataTable($('#aTbl', page), {
    rows: view,
    cols:[
      { key:'timestamp', label:'When', nowrap:true, render:a => fmtDT(a.timestamp) },
      { key:'employeeId', label:'User', nowrap:true, render:a => esc(a.employeeId) + '<span class="cellsub">' + esc(a.userName) + '</span>' },
      { key:'action', label:'Action', nowrap:true, render:a => '<span class="tag">' + esc(a.action) + '</span>' },
      { key:'ticketId', label:'Ticket', nowrap:true, render:a => a.ticketId ? '<span class="tid">' + esc(a.ticketId) + '</span>' : '—' },
      { key:'oldValue', label:'Previous', render:a => esc(a.oldValue || '—') },
      { key:'newValue', label:'New', render:a => esc(a.newValue || '—') },
      { key:'remarks', label:'Remarks', render:a => esc(a.remarks || '—') }
    ],
    emptyTitle:'No activity recorded'
  });
  function refilter(){
    const q = $('#aq').value.toLowerCase(), ac = $('#aa').value, f = $('#af').value, to = $('#at').value;
    view = Store.db.audit.filter(a => {
      if(ac && a.action !== ac) return false;
      if(f && ymd(a.timestamp) < f) return false;
      if(to && ymd(a.timestamp) > to) return false;
      return (a.employeeId + ' ' + a.userName + ' ' + a.action + ' ' + a.ticketId + ' ' + a.newValue + ' ' + a.remarks).toLowerCase().indexOf(q) >= 0;
    });
    t.redraw(view);
  }
  $('#aq', page).oninput = debounce(refilter, 200);
  ['aa','af','at'].forEach(id => $('#' + id, page).onchange = refilter);
  $('#ax', page).onclick = () => exportGeneric('Audit_Log', ['Timestamp','Employee ID','User','Action','Ticket ID','Previous Value','New Value','Remarks'],
    view.map(a => [fmtDT(a.timestamp), a.employeeId, a.userName, a.action, a.ticketId, a.oldValue, a.newValue, a.remarks]));
};

