VIEWS.settings = function(page){
  const cfg = Store.db.config;
  const listBox = (id, label, arr, hint) => '<div class="fld"><label>' + label + '</label>' +
    '<textarea class="inp" id="' + id + '" style="min-height:120px">' + esc(arr.join('\n')) + '</textarea>' +
    '<div class="hint">' + hint + '</div></div>';
  page.innerHTML = '<div style="max-width:900px"><div class="card"><div class="card-h"><h3>Dropdown values</h3>' +
    '<span class="spacer"></span><span class="mut sm">one value per line</span></div><div class="card-b"><div class="frow c2">' +
    listBox('cfgSeg', 'Customer segment', cfg.customerSegments, 'Used on the call log form and in filters.') +
    listBox('cfgPhase', 'Product phase', cfg.productPhases, 'Applies to both master and other products.') +
    listBox('cfgStatus', 'Call status', cfg.callStatuses, 'Removing a status does not change tickets already using it.') +
    listBox('cfgType', 'Support type', cfg.supportTypes, 'The remote / own-visit rules key off the exact wording.') +
    '</div><div class="frow c2"><div class="fld"><label>Ticket prefix</label><input class="inp" id="cfgPfx" value="' + esc(cfg.ticketPrefix) + '" maxlength="6">' +
    '<div class="hint">Ticket IDs look like ' + esc(cfg.ticketPrefix) + '-' + ymd().replace(/-/g, '') + '-0001.</div></div></div>' +
    '<div class="btn-row"><button class="btn pri" id="cfgSave">Save settings</button></div></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-h"><h3>Who can sign in</h3><span class="spacer"></span>' +
    '<span class="mut sm">' + Store.db.users.filter(u => u.role).length + ' of ' + Store.db.users.length + ' have a login</span></div><div class="card-b">' +
    '<p class="sm mut">Roles come from three named lists, not from a job title. Someone outside all three is kept in the ' +
    'directory but cannot sign in, and only the TRCE list appears in &ldquo;remote support assigned to&rdquo;. ' +
    'The lists are refreshed from sheets named <span class="mono">ADMIN</span>, <span class="mono">HELPDESK Team</span> and ' +
    '<span class="mono">TRCE USER</span> when you sync the user workbook.</p>' +
    '<div class="rl-grid">' + ['ADMIN','HELPDESK','TRCE'].map(r =>
      '<div class="rl-box" data-r="' + r + '"><div class="rl-h"><b>' + esc(ROLES[r].label) + '</b>' +
        '<span class="rl-n">' + ((cfg.roleLists || {})[r] || []).length + '</span></div>' +
        '<div class="rl-list" id="rl_' + r + '"></div>' +
        '<div class="rl-add"><div class="rl-cb" id="rlcb_' + r + '"></div></div></div>').join('') + '</div>' +
    '<div class="btn-row"><button class="btn pri" id="rlSave">Save role lists</button>' +
    '<button class="btn" id="openSync">Sync logins now</button></div></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-h"><h3>Your password</h3></div><div class="card-b">' +
    '<p class="sm mut" style="margin:0">Passwords are kept in the SharePoint <b>Users</b> list. To change one, update it there — ' +
    'the next sign-in uses the new password straight away.</p></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-h"><h3>Data</h3></div><div class="card-b">' +
    '<p class="sm mut">Calls, masters, history and the audit trail live in this browser under the key <span class="mono">' + DB_KEY + '</span>. ' +
    'Take a backup before clearing browser data, and move to the REST adapter when the Express + PostgreSQL backend is ready.</p>' +
    '<p class="sm mut">Photos are kept separately under <span class="mono">' + PHOTO_KEY + '</span> — currently ' +
    Store.db.calls.reduce((n, c) => n + ((c.photos || []).length), 0) + ' image(s), about ' + fmtBytes(PhotoStore.bytes()) + '.</p>' +
    '<div class="btn-row"><button class="btn" id="dbBackup">Download backup (JSON)</button>' +
    '<button class="btn" id="dbRestore">Restore from backup</button>' +
    (Store.db.calls.length ? '' : '<button class="btn" id="dbSample">Generate sample tickets</button>') +
    '<button class="btn dgr" id="dbReset">Reset to seed data</button></div>' +
    '<input type="file" id="dbFile" accept=".json" class="hide"></div></div></div>';

  $('#cfgSave', page).onclick = () => {
    const lines = id => $('#' + id).value.split('\n').map(s => s.trim()).filter(Boolean);
    try {
      API.saveConfig({ customerSegments:lines('cfgSeg'), productPhases:lines('cfgPhase'), callStatuses:lines('cfgStatus'),
        supportTypes:lines('cfgType'), ticketPrefix:$('#cfgPfx').value.trim().toUpperCase() || 'RCS' });
      toast('Settings saved.', 'ok'); go('settings');
    } catch(e){ toast(e.message, 'err'); }
  };
  /* ---- role membership editor ---- */
  const lists = API.roleLists();
  const nameOf = c => { const u = Store.db.users.find(x => x.employeeId === c); return u ? u.fullName : '(not in the user master)'; };
  const drawList = r => {
    const box = $('#rl_' + r, page);
    const codes = lists[r] || [];
    box.innerHTML = codes.length
      ? codes.map(c => '<div class="rl-row"><span><b>' + esc(c) + '</b> · ' + esc(nameOf(c)) + '</span>' +
          '<button class="rl-x" data-rm="' + esc(c) + '" data-r="' + r + '" title="Remove">&times;</button></div>').join('')
      : '<div class="rl-empty">No one on this list yet.</div>';
    const n = $('.rl-box[data-r="' + r + '"] .rl-n', page); if(n) n.textContent = codes.length;
  };
  ['ADMIN','HELPDESK','TRCE'].forEach(r => {
    drawList(r);
    Combobox($('#rlcb_' + r, page), {
      placeholder:'Add by employee code or name…',
      source: q => {
        const s = String(q || '').toLowerCase();
        if(!s) return [];
        return Store.db.users.filter(u => (u.employeeId + ' ' + u.fullName + ' ' + (u.branch || '')).toLowerCase().indexOf(s) >= 0)
          .slice(0, 25).map(u => ({ label:u.employeeId + ' — ' + u.fullName, sub:(u.branch || '').replace('_',' · '), u }));
      },
      onSelect: it => {
        if(!it) return;
        const code = it.u.employeeId;
        ['ADMIN','HELPDESK','TRCE'].forEach(x => { lists[x] = (lists[x] || []).filter(c => c !== code); });
        lists[r].push(code);
        ['ADMIN','HELPDESK','TRCE'].forEach(drawList);
      }
    });
  });
  page.addEventListener('click', e => {
    const b = e.target.closest('[data-rm]'); if(!b) return;
    lists[b.dataset.r] = (lists[b.dataset.r] || []).filter(c => c !== b.dataset.rm);
    drawList(b.dataset.r);
  });
  $('#openSync', page).onclick = () => openUserSync();
  $('#rlSave', page).onclick = () => {
    try {
      const r = API.saveRoleLists(lists);
      toast('Saved · ' + r.admin + ' admin, ' + r.helpdesk + ' helpdesk, ' + r.trce + ' TRCE — ' + r.logins + ' accounts can sign in.', 'ok');
      go('settings');
    } catch(e){ toast(e.message, 'err'); }
  };
  if($('#pwSave', page)) $('#pwSave', page).onclick = () => {
    const a = $('#pw1').value, b = $('#pw2').value;
    if(a !== b){ toast('The two passwords do not match.', 'err'); return; }
    try { API.changePassword(Session.user.employeeId, a); toast('Password changed.', 'ok'); $('#pw1').value = $('#pw2').value = ''; }
    catch(e){ toast(e.message, 'err'); }
  };
  $('#dbBackup', page).onclick = () => {
    download('rcm_backup_' + ymd().replace(/-/g, '') + '.json',
      new Blob([JSON.stringify({ db:Store.db, photos:PhotoStore.load(), exportedAt:new Date().toISOString() })], { type:'application/json' }));
    API.audit('BACKUP', '', '', 'database', '');
  };
  $('#dbRestore', page).onclick = () => $('#dbFile').click();
  $('#dbFile', page).onchange = async e => {
    const f = e.target.files[0]; if(!f) return;
    try {
      const raw = JSON.parse(await f.text());
      const db = raw.db || raw, pics = raw.photos || null;
      if(!db.schema || !db.calls) throw new Error('That file is not a valid backup.');
      confirmDlg('Restore backup', 'This replaces everything currently stored in this browser.', () => {
        Store.db = db; Store.save();
        if(pics){ PhotoStore.map = pics; PhotoStore.save(); }
        toast('Backup restored.', 'ok'); go('dashboard');
      }, 'Restore', true);
    } catch(err){ toast(err.message, 'err'); }
  };
    const sampleBtn = $('#dbSample', page);
  if(sampleBtn) sampleBtn.onclick = () => confirmDlg('Generate sample tickets',
    'Adds demo tickets spread over the last six months so the dashboard and reports have something to show. ' +
    'Only possible while the ticket list is empty.',
    () => { try { const n = API.sampleCalls(); toast(n + ' sample tickets generated.', 'ok'); go('settings'); }
            catch(e){ toast(e.message, 'err'); } }, 'Generate');
$('#dbReset', page).onclick = () => confirmDlg('Reset all data',
    'Every ticket, update and audit entry in this browser is removed and the demo data comes back. This cannot be undone.',
    () => { PhotoStore.reset(); Store.reset(); toast('Data reset.', 'ok'); location.reload(); }, 'Reset everything', true);
};

/* ============================================================
   POWER AUTOMATE WIRING (OPTION A - Local First with Sync)
   Pushes local changes to Power Automate flows in the background.
   ============================================================ */
if (CONFIG.adapter === 'local' && CONFIG.flows) {

  const runFlow = (url, payload) => {
    if (!url) return Promise.resolve(null);
    return fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(r => r.json()).catch(err => { console.error('Flow error:', err); return null; });
  };

  // 1. Record the sign-in centrally (AuditLog / LastLoginAt).
  //    Ticket sync itself already happens inside API.login (see "Background Sync" above) —
  //    it used to be fetched a second time here too, which raced the first response and
  //    could load either one depending on which reply landed last.
  //    (Sign-in now calls the login flow directly inside API.login — no second call here.)

  // 2. Call creation already reaches SharePoint synchronously inside API.createCall itself —
  //    it awaits Flow 3 and uses the server-assigned ticket ID before ever returning to the
  //    screen. Wrapping it here used to fire a *second* create against the same flow, leaving
  //    an orphan ticket in SharePoint every time (the app then switched to using this second,
  //    duplicate ticket's ID instead of the first one it had already shown the user).

  // 3. Push call updates / reassignments to SharePoint. This is the ONLY place that syncs an
  //    update — API.updateCall itself only writes to this device's local storage. If the push
  //    fails, flag the ticket so the next login sync (mergeServerCalls, above) keeps this
  //    device's copy instead of silently overwriting it with SharePoint's stale version, and
  //    tell the person so they know it hasn't gone through yet.
  const origUpdateCall = API.updateCall;
  API.updateCall = function(ticketId, p) {
    const c = origUpdateCall.call(this, ticketId, p);
    runFlow(CONFIG.flows.callUpdate, {
      ticketId: ticketId, employeeId: Session.user.employeeId,
      detailsIssueFound: p.detailsIssueFound || '', supportType: p.supportType || '',
      recipientType: p.recipientType || '', givenToId: p.givenToId || '', givenToName: p.givenToName || '',
      otherUser: p.otherRecipient || {}, directCustomer: p.directCustomer || {},
      supportiveEngineerId: p.supportEngineerId || '', supportiveEngineerName: p.supportEngineerName || '',
      correctiveAction: p.correctiveAction || '', spareRequired: p.spareRequired || 'No',
      spareName: p.spareName || '', tatSlab: p.tatSlab || '', callStatus: p.callStatus
    }).then(res => {
      if (res && res.ok) {
        if (c.pendingSync) delete c.pendingSync;
      } else {
        c.pendingSync = true;
        toast('Update to ' + ticketId + ' is saved on this device but hasn\'t reached SharePoint yet. It will retry the next time you sign in.', 'warn');
      }
      Store.save();
    });
    return c;
  };

  // 4. Photo upload already reaches SharePoint inside API.addPhotos itself (one POST per
  //    photo, with the returned URL saved onto the ticket). Wrapping it here used to upload
  //    every photo a second time — its result was discarded, but SharePoint still ended up
  //    with two copies of each file.

  // 5. Push User Sync to SharePoint (Flow 7) — API.syncUsers itself is local-only, so this is
  //    the only path that carries a fresh user import back to the SharePoint Users list.
  const origSyncUsers = API.syncUsers;
  API.syncUsers = function(rows, sourceLabel, opts) {
    const res = origSyncUsers.call(this, rows, sourceLabel, opts);
    const payload = {
      users: rows.map(r => ({
        employeeId: String(r.EmpCode || r['Employee ID'] || r.employeeId || '').trim().toUpperCase(),
        fullName: String(r.FullName || r['Full Name'] || r.fullName || '').trim(),
        password: String(r.Password || r.password || '').trim(),
        role: (Store.db.config.roleMap[String(r.Role || '').trim().toLowerCase()] || 'TRCE'),
        branch: String(r.Branch || '').trim() || String(r.Location || r.location || '').trim().replace('-', '_'),
        zone: String(r.Zone || '').trim(),
        designation: String(r.Designation || r['Job Title'] || '').trim(),
        department: "Operation",
        managerCode: String(r.ManagerCode || '').trim(),
        managerName: String(r.ManagerName || '').trim(),
        active: 1
      })).filter(r => r.employeeId && r.fullName)
    };
    /* Only an admin-run sync goes to SharePoint. The automatic read of users.json
       when the page opens happens before anyone signs in, so it is skipped here —
       otherwise every visit ran the flow and showed a warning if it failed. */
    if (Session.user && can('user.manage')) {
      runFlow(CONFIG.flows.usersSync, payload).then(res => {
        if (!res || !res.ok) toast('User list saved on this device but the SharePoint sync did not confirm — check the flow run history.', 'warn');
      });
    }
    return res;
  };
}
